window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2020-1-2"]={"track":"written","round":"2020-1-2","questions":[{"id":"written-2020-1-2-1","no":1,"unit":"소프트웨어 설계","q":"검토회의 전에 요구사항 명세서를 미리 배포하여 사전 검토한 후 짧은 검토 회의를 통해 오류를 조기에 검출하는데 목적을 두는 요구 사항 검토 방법은?","choices":["빌드 검증","동료 검토","워크 스루","개발자 검토"],"ans":3,"rate":69,"wiki":[{"title":"정적 테스트","url":"https://itwiki.kr/w/정적 테스트"}],"exp":{"concept":"요구사항 검토 방법에는 동료 검토, 워크스루, 인스펙션이 있다. 워크스루(Walk-through)는 검토 자료를 회의 전에 미리 나눠 주고 각자 읽어 온 뒤, 짧은 회의로 오류를 일찍 찾아내는 방식이다. 시험 전에 시험 범위를 미리 나눠 주고 짧게 질문만 받는 수업과 비슷하다.","choices":[{"verdict":"오답","why":"빌드 검증은 소스를 컴파일·빌드해 실행 가능한 결과물이 제대로 만들어지는지 확인하는 활동으로, 요구사항 명세서를 사전 배포해 검토하는 방법이 아니다."},{"verdict":"오답","why":"동료 검토(Peer Review)는 명세서 작성자가 동료들에게 내용을 직접 설명하고 동료들이 결함을 찾는 방법이다. 사전 배포 후 짧은 회의라는 특징은 워크스루에 해당한다."},{"verdict":"정답","why":"워크스루는 명세서를 회의 전에 미리 배포해 사전 검토하게 한 뒤 짧은 검토 회의로 오류를 조기에 검출하는 방법이므로 설명과 일치한다."},{"verdict":"오답","why":"개발자 검토는 요구사항 검토 방법으로 분류되는 표준 용어가 아니다."}],"keywords":[{"term":"워크스루(Walk-through)","desc":"사전 배포, 사전 검토 후 짧은 회의로 오류를 조기 검출"},{"term":"동료 검토(Peer Review)","desc":"작성자가 설명하고 동료들이 결함을 찾는 방법"},{"term":"인스펙션(Inspection)","desc":"작성자를 제외한 전문가들이 명세서를 꼼꼼히 확인하며 결함을 찾는 공식 검토"}],"memo":"미리 배포하고 짧게 회의하면 워크스루, 작성자가 직접 설명하면 동료 검토, 작성자 빼고 전문가가 따지면 인스펙션."}},{"id":"written-2020-1-2-2","no":2,"unit":"소프트웨어 설계","q":"코드 설계에서 일정한 일련번호를 부여하는 방식의 코드는?","choices":["연상 코드","블록 코드","순차 코드","표의 숫자 코드"],"ans":3,"rate":76,"wiki":[{"title":"코드","url":"https://itwiki.kr/w/코드"}],"exp":{"concept":"코드는 자료를 쉽게 구분하려고 붙이는 번호나 기호다. 순차 코드는 자료가 생긴 순서나 일정한 기준에 따라 1, 2, 3처럼 차례대로 일련번호를 붙이는 가장 단순한 방식이다. 출석부 번호를 떠올리면 된다.","choices":[{"verdict":"오답","why":"연상 코드(Mnemonic Code)는 TV-40처럼 코드만 보고도 대상이 무엇인지 떠올릴 수 있도록 이름이나 약호를 섞어 만든 코드다."},{"verdict":"오답","why":"블록 코드(Block Code)는 공통 성질을 가진 자료끼리 묶어 블록으로 구분하고, 각 블록 안에서 번호를 매기는 구분 코드다."},{"verdict":"정답","why":"순차 코드(Sequence Code)는 자료의 발생 순서나 크기 순서 등 일정 기준에 따라 차례로 일련번호를 부여하는 코드이므로 정답이다."},{"verdict":"오답","why":"표의 숫자 코드(Significant Digit Code)는 대상의 길이, 무게, 용량 같은 물리적 수치를 코드에 그대로 넣는 방식이다. 유효 숫자 코드라고도 한다."}],"keywords":[{"term":"순차 코드","desc":"일정 기준에 따라 차례로 일련번호 부여"},{"term":"블록 코드","desc":"공통 성질별로 블록을 나눠 번호 부여, 구분 코드"},{"term":"연상 코드","desc":"명칭이나 약호를 섞어 대상을 연상할 수 있게 함"},{"term":"표의 숫자 코드","desc":"길이, 무게 등 물리적 수치를 코드에 그대로 사용"}],"memo":"일련번호면 순차, 묶어서 구간이면 블록, 보면 떠오르면 연상, 수치가 들어가면 표의 숫자."}},{"id":"written-2020-1-2-3","no":3,"unit":"소프트웨어 설계","q":"객체지향 프로그램에서 데이터를 추상화하는 단위는?","choices":["메소드","클래스","상속성","메시지"],"ans":2,"rate":76,"wiki":[{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"추상화는 복잡한 것에서 공통되고 중요한 특징만 뽑아 내는 것이다. 객체지향에서는 비슷한 객체들의 공통 속성(데이터)과 동작(메소드)을 묶어 클래스로 정의하므로, 데이터를 추상화하는 단위는 클래스다. 붕어빵 틀이 클래스, 구워진 붕어빵 하나하나가 객체다.","choices":[{"verdict":"오답","why":"메소드(Method)는 객체가 수행하는 동작, 즉 연산을 구현한 함수다. 데이터를 추상화하는 단위가 아니다."},{"verdict":"정답","why":"클래스(Class)는 공통 속성과 연산을 가진 객체들을 하나로 묶어 정의한 틀로, 데이터를 추상화하는 단위이므로 정답이다."},{"verdict":"오답","why":"상속성(Inheritance)은 상위 클래스의 속성과 연산을 하위 클래스가 물려받는 성질이다. 추상화의 단위가 아니다."},{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 동작을 하라고 요청하는 수단이다."}],"keywords":[{"term":"클래스","desc":"공통 속성과 연산을 묶은 객체의 틀, 데이터 추상화의 단위"},{"term":"객체(Object)","desc":"클래스로부터 만들어진 실제 실체, 인스턴스"},{"term":"메시지","desc":"객체에게 연산 수행을 요청하는 수단"}],"memo":"틀은 클래스, 틀로 찍어 낸 것은 객체(인스턴스)다."}},{"id":"written-2020-1-2-4","no":4,"unit":"소프트웨어 설계","q":"데이터 흐름도(DFD)의 구성요소에 포함되지 않는 것은?","choices":["process","data flow","data store","data dictionary"],"ans":4,"rate":71,"wiki":[{"title":"자료 흐름도","url":"https://itwiki.kr/w/자료 흐름도"}],"exp":{"concept":"데이터 흐름도(DFD, Data Flow Diagram)는 자료가 시스템 안에서 어떻게 흘러가고 처리되는지를 그림으로 나타낸 도구다. 구성 요소는 처리(Process), 자료 흐름(Data Flow), 자료 저장소(Data Store), 단말(Terminator) 네 가지다. 자료 사전은 DFD에 나오는 자료를 따로 정의하는 별도의 문서다.","choices":[{"verdict":"오답","why":"프로세스(Process)는 입력 자료를 출력 자료로 바꾸는 처리 과정으로, 원으로 표시하는 DFD의 구성 요소다."},{"verdict":"오답","why":"자료 흐름(Data Flow)은 자료가 이동하는 경로로, 화살표로 표시하는 DFD의 구성 요소다."},{"verdict":"오답","why":"자료 저장소(Data Store)는 자료가 저장되는 곳으로, 평행한 두 직선으로 표시하는 DFD의 구성 요소다."},{"verdict":"정답","why":"자료 사전(Data Dictionary)은 DFD에 나타난 자료의 의미와 구성을 정의하는 별도의 도구로, DFD 자체의 구성 요소가 아니므로 정답이다."}],"keywords":[{"term":"DFD 구성 요소","desc":"처리(원), 자료 흐름(화살표), 자료 저장소(평행선), 단말(사각형)"},{"term":"자료 사전(DD)","desc":"자료 흐름도에 나오는 자료를 정의하고 기록한 사전"},{"term":"구조적 분석 도구","desc":"DFD, 자료 사전, 소단위 명세서, 개체 관계도, 상태 전이도"}],"memo":"DFD는 그림 4개(처리, 흐름, 저장소, 단말), 자료 사전은 그림이 아니라 정의서다."}},{"id":"written-2020-1-2-5","no":5,"unit":"소프트웨어 설계","q":"소프트웨어 설계시 구축된 플랫폼의 성능특성 분석에 사용되는 측정 항목이 아닌 것은?","choices":["응답시간(Response Time)","가용성(Availability)","사용률(Utilization)","서버 튜닝(Server Tuning)"],"ans":4,"rate":86,"exp":{"concept":"플랫폼의 성능을 분석할 때는 측정할 수 있는 수치를 본다. 대표 항목은 응답 시간, 가용성, 사용률, 경과 시간이다. 서버 튜닝은 성능을 높이려고 설정을 조정하는 작업이지 측정 항목이 아니다.","choices":[{"verdict":"오답","why":"응답 시간(Response Time)은 요청을 보낸 뒤 첫 응답이 오기까지 걸린 시간으로, 성능 특성 측정 항목이다."},{"verdict":"오답","why":"가용성(Availability)은 시스템을 필요할 때 사용할 수 있는 정도로, 성능 특성 측정 항목이다."},{"verdict":"오답","why":"사용률(Utilization)은 작업을 처리하는 동안 CPU, 메모리 등 자원이 사용된 비율로, 성능 특성 측정 항목이다."},{"verdict":"정답","why":"서버 튜닝(Server Tuning)은 측정 결과를 바탕으로 서버 설정을 조정해 성능을 개선하는 작업이다. 측정하는 항목이 아니라 개선 활동이므로 정답이다."}],"keywords":[{"term":"응답 시간","desc":"요청 후 응답이 시작될 때까지의 시간"},{"term":"경과 시간(Turnaround Time)","desc":"작업 요청부터 처리 완료까지 걸린 전체 시간"},{"term":"사용률","desc":"작업 처리 중 자원이 사용된 비율"},{"term":"가용성","desc":"필요할 때 시스템을 사용할 수 있는 정도"}],"memo":"측정 항목은 숫자로 재는 것(응답 시간, 경과 시간, 사용률, 가용성)이고, 튜닝은 재고 나서 하는 일이다."}},{"id":"written-2020-1-2-6","no":6,"unit":"소프트웨어 설계","q":"UML 확장 모델에서 스테레오 타입 객체를 표현할 때 사용하는 기호로 맞는 것은?","choices":["《 》","(( ))","{{ }}","[[ ]]"],"ans":1,"rate":76,"exp":{"concept":"UML의 스테레오타입(Stereotype)은 기본 UML 요소에 의미를 덧붙여 확장할 때 쓰는 표기다. 겹화살괄호 《 》 안에 이름을 적는다. 예를 들어 《include》, 《extend》, 《interface》처럼 쓴다.","choices":[{"verdict":"정답","why":"스테레오타입은 길러멧(guillemet)이라 부르는 겹화살괄호 《 》 안에 이름을 적어 표현하므로 정답이다."},{"verdict":"오답","why":"(( ))는 UML에서 스테레오타입을 표기하는 기호가 아니다."},{"verdict":"오답","why":"{ }는 UML에서 제약 조건(Constraint)을 적을 때 쓰는 기호이며, {{ }} 형태는 스테레오타입 표기가 아니다."},{"verdict":"오답","why":"[[ ]]는 UML에서 스테레오타입을 표기하는 기호가 아니다."}],"keywords":[{"term":"스테레오타입","desc":"UML 요소에 의미를 추가해 확장하는 표기, 《 》 사용"},{"term":"《include》","desc":"유스케이스 포함 관계에 쓰는 스테레오타입"},{"term":"《extend》","desc":"유스케이스 확장 관계에 쓰는 스테레오타입"}],"memo":"《include》, 《extend》를 떠올리면 스테레오타입 기호가 《 》임을 바로 알 수 있다."}},{"id":"written-2020-1-2-7","no":7,"unit":"소프트웨어 설계","q":"GoF(Gang of Four)의 디자인 패턴에서 행위 패턴에 속하는 것은?","choices":["Builder","Visitor","Prototype","Bridge"],"ans":2,"rate":55,"exp":{"concept":"GoF 디자인 패턴 23개는 목적에 따라 생성, 구조, 행위 패턴으로 나뉜다. 생성 패턴은 객체를 만드는 방법, 구조 패턴은 클래스와 객체를 조합하는 방법, 행위 패턴은 객체들이 일을 나누고 소통하는 방법을 다룬다. Visitor는 행위 패턴이다.","choices":[{"verdict":"오답","why":"Builder는 복잡한 객체를 단계별로 조립해 만드는 생성 패턴이다."},{"verdict":"정답","why":"Visitor는 객체 구조는 그대로 두고 그 원소에 수행할 새 연산을 별도 클래스로 분리하는 행위 패턴이므로 정답이다."},{"verdict":"오답","why":"Prototype은 원본 객체를 복제해 새 객체를 만드는 생성 패턴이다."},{"verdict":"오답","why":"Bridge는 기능의 계층과 구현의 계층을 분리해 각각 독립적으로 확장할 수 있게 하는 구조 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"Abstract Factory, Builder, Factory Method, Prototype, Singleton"},{"term":"구조 패턴","desc":"Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행위 패턴","desc":"Chain of Responsibility, Command, Interpreter, Iterator, Mediator, Memento, Observer, State, Strategy, Template Method, Visitor"}],"memo":"생성 5개와 구조 7개를 외우고, 나머지 11개는 행위 패턴으로 처리하면 빠르다."}},{"id":"written-2020-1-2-8","no":8,"unit":"소프트웨어 설계","q":"자료 사전에서 자료의 생략을 의미하는 기호는?","choices":["{ }","**","=","(　)"],"ans":4,"rate":66,"wiki":[{"title":"자료 사전","url":"https://itwiki.kr/w/자료 사전"}],"exp":{"concept":"자료 사전은 자료의 구성을 정해진 기호로 적는다. =는 정의, +는 연결, [ ]는 선택, { }는 반복, ( )는 생략 가능, **는 주석을 뜻한다.","choices":[{"verdict":"오답","why":"{ }는 같은 항목이 여러 번 나오는 반복을 뜻한다."},{"verdict":"오답","why":"**는 설명을 덧붙이는 주석(Comment)을 뜻한다."},{"verdict":"오답","why":"=는 왼쪽 자료가 오른쪽으로 구성된다는 정의를 뜻한다."},{"verdict":"정답","why":"( )는 해당 항목이 있어도 되고 없어도 되는 생략 가능을 뜻하므로 정답이다."}],"keywords":[{"term":"= (정의)","desc":"자료가 무엇으로 구성되는지 정의"},{"term":"+ (연결)","desc":"자료와 자료를 이어서 구성"},{"term":"[ ] (선택)","desc":"여러 항목 중 하나를 선택, 항목 구분은 |"},{"term":"{ } (반복)","desc":"항목이 여러 번 반복"},{"term":"( ) (생략)","desc":"있어도 되고 없어도 되는 항목"}],"memo":"괄호 모양으로 구분: 둥근 ( )는 생략, 대괄호 [ ]는 선택, 중괄호 { }는 반복, **는 주석."}},{"id":"written-2020-1-2-9","no":9,"unit":"소프트웨어 설계","q":"트랜잭션이 올바르게 처리되고 있는지 데이터를 감시하고 제어하는 미들웨어는?","choices":["RPC","ORB","TP monitor","HUB"],"ans":3,"rate":76,"wiki":[{"title":"TP 모니터","url":"https://itwiki.kr/w/TP 모니터"}],"exp":{"concept":"미들웨어는 서로 다른 시스템이나 프로그램 사이에서 다리 역할을 하는 소프트웨어다. 그중 TP 모니터(Transaction Processing Monitor)는 항공 예약, 은행 업무처럼 트랜잭션이 많은 환경에서 트랜잭션이 올바르게 처리되는지 감시하고 제어한다.","choices":[{"verdict":"오답","why":"RPC(Remote Procedure Call)는 원격지에 있는 프로그램의 프로시저를 내 프로그램의 함수처럼 호출해 쓰게 해 주는 미들웨어다."},{"verdict":"오답","why":"ORB(Object Request Broker)는 객체지향 환경에서 클라이언트와 서버 객체 사이의 요청을 중개하는 미들웨어로, CORBA 표준의 핵심 요소다."},{"verdict":"정답","why":"TP 모니터는 온라인 트랜잭션 처리 환경에서 트랜잭션이 올바르게 처리되는지 데이터를 감시하고 제어하는 미들웨어이므로 정답이다."},{"verdict":"오답","why":"허브(HUB)는 여러 장비를 하나의 네트워크로 연결하는 네트워크 장비로, 트랜잭션을 감시하는 미들웨어가 아니다."}],"keywords":[{"term":"TP 모니터","desc":"트랜잭션 처리를 감시·제어하는 미들웨어"},{"term":"RPC","desc":"원격 프로시저를 로컬 함수처럼 호출"},{"term":"ORB","desc":"객체 간 요청을 중개, CORBA 기반"},{"term":"MOM(Message Oriented Middleware)","desc":"메시지 기반 비동기 통신 미들웨어"}],"memo":"Transaction Processing이라는 이름 그대로, 트랜잭션 감시는 TP 모니터."}},{"id":"written-2020-1-2-10","no":10,"unit":"소프트웨어 설계","q":"UI 설계 원칙에서 누구나 쉽게 이해하고 사용할 수 있어야 한다는 것은?","choices":["유효성","직관성","무결성","유연성"],"ans":2,"rate":90,"wiki":[{"title":"직관성","url":"https://itwiki.kr/w/직관성"}],"exp":{"concept":"UI 설계 원칙은 직관성, 유효성, 학습성, 유연성 네 가지다. 그중 직관성은 설명서 없이도 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙이다. 처음 보는 엘리베이터도 버튼만 보고 바로 쓸 수 있는 것이 직관성이다.","choices":[{"verdict":"오답","why":"유효성은 사용자의 목적을 정확하고 완벽하게 달성할 수 있어야 한다는 원칙이다."},{"verdict":"정답","why":"직관성은 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙이므로 정답이다."},{"verdict":"오답","why":"무결성은 데이터가 정확하고 일관되게 유지되는 성질로, UI 설계 원칙에 속하지 않는다."},{"verdict":"오답","why":"유연성은 사용자의 요구 사항을 최대한 수용하고 실수를 최소화해야 한다는 원칙이다."}],"keywords":[{"term":"직관성","desc":"누구나 쉽게 이해하고 사용"},{"term":"유효성","desc":"사용자의 목적을 정확하고 완벽하게 달성"},{"term":"학습성","desc":"누구나 쉽게 배우고 익힐 수 있음"},{"term":"유연성","desc":"사용자 요구를 최대한 수용하고 실수를 최소화"}],"memo":"UI 설계 원칙은 직관성, 유효성, 학습성, 유연성. 무결성은 데이터베이스 쪽 용어다."}},{"id":"written-2020-1-2-11","no":11,"unit":"소프트웨어 설계","q":"XP(eXtreme Programming)의 5가지 가치로 거리가 먼 것은?","choices":["용기","의사소통","정형분석","피드백"],"ans":3,"rate":75,"wiki":[{"title":"익스트림 프로그래밍","url":"https://itwiki.kr/w/익스트림 프로그래밍"}],"exp":{"concept":"XP(eXtreme Programming)는 짧은 주기로 자주 배포하며 고객 요구 변화에 빠르게 대응하는 애자일 방법론이다. XP가 내세우는 5가지 가치는 용기, 단순성, 의사소통, 피드백, 존중이다.","choices":[{"verdict":"오답","why":"용기(Courage)는 고객 요구 변화에 과감하게 대응하는 태도로, XP의 5가지 가치에 속한다."},{"verdict":"오답","why":"의사소통(Communication)은 개발자, 고객, 관리자 사이의 원활한 소통으로, XP의 5가지 가치에 속한다."},{"verdict":"정답","why":"정형 분석은 수학적 기법으로 명세를 엄밀하게 분석하는 방법으로, XP의 가치가 아니므로 정답이다."},{"verdict":"오답","why":"피드백(Feedback)은 결과를 빠르게 확인하고 반영하는 것으로, XP의 5가지 가치에 속한다."}],"keywords":[{"term":"XP 5가지 가치","desc":"용기, 단순성, 의사소통, 피드백, 존중"},{"term":"짝 프로그래밍(Pair Programming)","desc":"두 명이 한 컴퓨터에서 함께 코딩하는 XP 실천 사항"},{"term":"테스트 주도 개발(TDD)","desc":"테스트를 먼저 작성하고 그것을 통과하는 코드를 작성"}],"memo":"XP 가치는 용단의피존(용기, 단순성, 의사소통, 피드백, 존중)."}},{"id":"written-2020-1-2-12","no":12,"unit":"소프트웨어 설계","q":"UML 모델에서 사용하는 Structural Diagram 에 속하지 않은 것은?","choices":["Class Diagram","Object Diagram","Component Diagram","Activity Diagram"],"ans":4,"rate":74,"wiki":[{"title":"UML","url":"https://itwiki.kr/w/UML"}],"exp":{"concept":"UML 다이어그램은 시스템의 정적인 구조를 보여 주는 구조적 다이어그램과, 시간에 따른 동작을 보여 주는 행위 다이어그램으로 나뉜다. 활동 다이어그램은 처리 흐름을 순서대로 보여 주므로 행위 다이어그램이다.","choices":[{"verdict":"오답","why":"클래스 다이어그램은 클래스의 속성, 연산과 클래스 사이의 관계를 표현하는 구조적 다이어그램이다."},{"verdict":"오답","why":"객체 다이어그램은 클래스에 속한 실제 객체(인스턴스)와 그 관계를 표현하는 구조적 다이어그램이다."},{"verdict":"오답","why":"컴포넌트 다이어그램은 컴포넌트 사이의 관계와 인터페이스를 표현하는 구조적 다이어그램이다."},{"verdict":"정답","why":"활동 다이어그램(Activity Diagram)은 시스템이 수행하는 처리의 흐름을 순서대로 표현하는 행위 다이어그램이므로 정답이다."}],"keywords":[{"term":"구조적 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지"},{"term":"행위 다이어그램","desc":"유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 타이밍"},{"term":"활동 다이어그램","desc":"처리 흐름을 순서에 따라 표현"}],"memo":"이름에 동작 느낌(활동, 상태, 시퀀스, 유스케이스)이 있으면 행위, 구성품 느낌(클래스, 객체, 컴포넌트, 배치, 패키지)이면 구조."}},{"id":"written-2020-1-2-13","no":13,"unit":"소프트웨어 설계","q":"소프트웨어 개발 방법 중 요구사항 분석(requirements annalysis)과 거리가 먼 것은?","choices":["비용과 일정에 대한 제약설정","타당성 조사","요구사항 정의 문서화","설계 명세서 작성"],"ans":4,"rate":57,"wiki":[{"title":"요구사항 분석","url":"https://itwiki.kr/w/요구사항 분석"}],"exp":{"concept":"요구사항 분석은 무엇을 만들어야 하는지 정리하는 단계다. 타당성 조사, 비용과 일정 제약 설정, 요구사항 정의와 문서화가 여기에 들어간다. 어떻게 만들지를 정하는 설계 명세서 작성은 다음 단계인 설계 단계의 일이다.","choices":[{"verdict":"오답","why":"비용과 일정에 대한 제약 설정은 요구사항 분석 단계에서 개발 범위와 함께 정하는 활동이다."},{"verdict":"오답","why":"타당성 조사는 개발이 기술, 경제, 법적으로 가능한지 따지는 활동으로 요구사항 분석 초기에 수행한다."},{"verdict":"오답","why":"요구사항 정의 문서화는 분석한 요구사항을 명세서로 정리하는 요구사항 분석 단계의 활동이다."},{"verdict":"정답","why":"설계 명세서 작성은 요구사항을 바탕으로 시스템 구조를 정하는 설계 단계의 활동이므로 요구사항 분석과 거리가 멀다."}],"keywords":[{"term":"요구사항 분석","desc":"사용자 요구를 이해하고 무엇을 개발할지 정리하는 단계"},{"term":"타당성 조사","desc":"기술적, 경제적, 법적 실현 가능성 검토"},{"term":"요구사항 명세서","desc":"분석한 요구사항을 정리한 문서, 설계의 입력"}],"memo":"분석은 무엇을(What), 설계는 어떻게(How). 설계 명세서는 How 쪽이다."}},{"id":"written-2020-1-2-14","no":14,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh)의 객체지향 분석 절차를 가장 바르게 나열한 것은?","choices":["객체 모형→동적 모형→기능 모형","객체 모형→기능 모형→동적 모형","기능 모형→동적 모형→객체 모형","기능 모형→객체 모형→동적 모형"],"ans":1,"rate":75,"wiki":[{"title":"럼바우 분석 기법","url":"https://itwiki.kr/w/럼바우 분석 기법"}],"exp":{"concept":"럼바우(Rumbaugh)의 객체 모델링 기법(OMT)은 시스템을 세 가지 모형으로 분석한다. 먼저 객체와 관계를 정의하는 객체 모형, 다음으로 시간에 따른 상태 변화를 그리는 동적 모형, 마지막으로 자료 흐름을 그리는 기능 모형 순서로 진행한다.","choices":[{"verdict":"정답","why":"럼바우 분석 절차는 객체 모형(객체 다이어그램), 동적 모형(상태 다이어그램), 기능 모형(자료 흐름도) 순서이므로 정답이다."},{"verdict":"오답","why":"기능 모형은 마지막 단계이며, 동적 모형보다 앞서지 않는다."},{"verdict":"오답","why":"기능 모형이 처음에 오지 않는다. 럼바우는 객체 모형부터 시작한다."},{"verdict":"오답","why":"기능 모형부터 시작하는 순서는 럼바우 절차가 아니다."}],"keywords":[{"term":"객체 모형","desc":"객체와 객체 사이의 관계 정의, 객체 다이어그램 사용"},{"term":"동적 모형","desc":"시간 흐름에 따른 객체의 상태 변화, 상태 다이어그램 사용"},{"term":"기능 모형","desc":"입력에서 출력까지 자료 흐름, 자료 흐름도(DFD) 사용"}],"memo":"럼바우는 객동기(객체, 동적, 기능) 순서."}},{"id":"written-2020-1-2-15","no":15,"unit":"소프트웨어 설계","q":"공통 모듈에 대한 명세 기법 중 해당 기능에 대해 일관되게 이해하고 한 가지로 해석될 수 있도록 작성하는 원칙은?","choices":["상호작용성","명확성","독립성","내용성"],"ans":2,"rate":83,"wiki":[{"title":"공통 모듈","url":"https://itwiki.kr/w/공통 모듈"}],"exp":{"concept":"공통 모듈 명세 기법은 여러 곳에서 함께 쓰는 모듈의 기능을 문서로 정의할 때 지켜야 할 원칙이다. 정확성, 명확성, 완전성, 일관성, 추적성이 있다. 그중 명확성은 누가 읽어도 한 가지 뜻으로만 해석되게 쓰라는 원칙이다.","choices":[{"verdict":"오답","why":"상호작용성은 공통 모듈 명세 기법의 원칙에 속하지 않는다."},{"verdict":"정답","why":"명확성은 해당 기능을 일관되게 이해하고 한 가지로 해석될 수 있도록 작성하는 원칙이므로 정답이다."},{"verdict":"오답","why":"독립성은 모듈이 다른 모듈에 덜 의존하는 성질로, 공통 모듈 명세 기법의 원칙이 아니다."},{"verdict":"오답","why":"내용성은 공통 모듈 명세 기법의 원칙에 속하지 않는다."}],"keywords":[{"term":"정확성","desc":"시스템 구현 시 필요한 기능인지 알 수 있도록 정확히 작성"},{"term":"명확성","desc":"한 가지로만 해석되도록 작성"},{"term":"완전성","desc":"구현에 필요한 모든 것을 기술"},{"term":"일관성","desc":"공통 기능 사이에 충돌이 없도록 작성"},{"term":"추적성","desc":"기능의 요구사항 출처와 관련 시스템을 추적할 수 있도록 작성"}],"memo":"공통 모듈 명세 원칙은 정명완일추(정확성, 명확성, 완전성, 일관성, 추적성). 한 가지 해석이면 명확성."}},{"id":"written-2020-1-2-16","no":16,"unit":"소프트웨어 설계","q":"객체지향 기법에서 클래스들 사이의 ‘부분-전체(part-whole)' 관계 또는 ’부분(is-a-part-of)'의 관계로 설명되는 연관성을 나타내는 용어는?","choices":["일반화","추상화","캡슐화","집단화"],"ans":4,"rate":52,"wiki":[{"title":"객체지향 연관성","url":"https://itwiki.kr/w/객체지향 연관성"},{"title":"객체지향 기법","url":"https://itwiki.kr/w/객체지향 기법"}],"exp":{"concept":"객체지향에서 클래스 사이 관계 중 집단화(Aggregation)는 여러 부분 클래스가 모여 하나의 전체 클래스를 이루는 관계다. 바퀴, 엔진, 핸들이 모여 자동차가 되는 것처럼 부분과 전체(part-whole, is-a-part-of) 관계를 나타낸다.","choices":[{"verdict":"오답","why":"일반화(Generalization)는 하위 클래스들의 공통점을 묶어 상위 클래스로 표현하는 is-a 관계다."},{"verdict":"오답","why":"추상화(Abstraction)는 불필요한 세부 사항을 감추고 핵심 특징만 뽑아 내는 원리로, 부분과 전체 관계를 뜻하지 않는다."},{"verdict":"오답","why":"캡슐화(Encapsulation)는 데이터와 그 데이터를 다루는 연산을 하나로 묶고 내부를 감추는 원리다."},{"verdict":"정답","why":"집단화는 부분 객체들이 모여 전체 객체를 이루는 part-whole 관계이므로 정답이다."}],"keywords":[{"term":"집단화(Aggregation)","desc":"부분과 전체 관계, is-a-part-of"},{"term":"일반화(Generalization)","desc":"상위와 하위 클래스 관계, is-a"},{"term":"연관화(Association)","desc":"클래스들이 서로 참조하는 is-member-of 관계"}],"memo":"is-a는 일반화, is-a-part-of는 집단화. part가 보이면 집단화다."}},{"id":"written-2020-1-2-17","no":17,"unit":"소프트웨어 설계","q":"CASE가 갖고 있는 주요 기능이 아닌 것은?","choices":["그래픽 지원","소프트웨어 생명주기 전 단계의 연결","언어번역","다양한 소프트웨어 개발 모형 지원"],"ans":3,"rate":74,"wiki":[{"title":"CASE","url":"https://itwiki.kr/w/CASE"}],"exp":{"concept":"CASE(Computer Aided Software Engineering)는 소프트웨어 개발 과정을 컴퓨터로 자동화해 돕는 도구다. 주요 기능은 생명주기 전 단계의 연결, 다양한 개발 모형 지원, 그래픽(다이어그램) 지원 등이다. 소스 언어를 기계어로 번역하는 일은 컴파일러의 역할이다.","choices":[{"verdict":"오답","why":"그래픽 지원은 DFD, ERD 같은 다이어그램을 그려 주는 CASE의 주요 기능이다."},{"verdict":"오답","why":"소프트웨어 생명주기 전 단계의 연결은 분석부터 유지보수까지 산출물을 이어 주는 CASE의 주요 기능이다."},{"verdict":"정답","why":"언어 번역은 컴파일러나 인터프리터 같은 언어 번역기의 기능이며 CASE의 주요 기능이 아니므로 정답이다."},{"verdict":"오답","why":"다양한 소프트웨어 개발 모형 지원은 폭포수, 프로토타입 등 여러 모형을 지원하는 CASE의 주요 기능이다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발 과정을 자동화해 지원하는 도구"},{"term":"상위 CASE","desc":"요구 분석과 설계 단계 지원"},{"term":"하위 CASE","desc":"코드 생성, 테스트, 문서화 단계 지원"}],"memo":"CASE는 개발을 돕는 도구, 번역은 컴파일러. 언어 번역이 나오면 CASE 기능이 아니다."}},{"id":"written-2020-1-2-18","no":18,"unit":"소프트웨어 설계","q":"DBMS 분석시 고려사항으로 거리가 먼 것은?","choices":["가용성","성능","네트워크 구성도","상호 호환성"],"ans":3,"rate":80,"wiki":[{"title":"DBMS","url":"https://itwiki.kr/w/DBMS"}],"exp":{"concept":"DBMS를 고를 때는 가용성, 성능, 상호 호환성, 기술 지원, 구축 비용을 따진다. 모두 DBMS 제품 자체의 특성이다. 네트워크 구성도는 시스템 구축 환경에 관한 문서로, DBMS 분석 항목이 아니다.","choices":[{"verdict":"오답","why":"가용성은 장시간 운영 시 장애 없이 쓸 수 있는지, 백업과 복구 기능이 있는지를 보는 DBMS 분석 고려 사항이다."},{"verdict":"오답","why":"성능은 대량 거래 처리 성능, 다양한 질의 처리 능력 등을 보는 DBMS 분석 고려 사항이다."},{"verdict":"정답","why":"네트워크 구성도는 서버와 장비의 연결 구조를 그린 문서로, DBMS 분석 고려 사항이 아니므로 정답이다."},{"verdict":"오답","why":"상호 호환성은 설치 가능한 운영체제 종류, 드라이버 지원 등을 보는 DBMS 분석 고려 사항이다."}],"keywords":[{"term":"DBMS 분석 고려 사항","desc":"가용성, 성능, 상호 호환성, 기술 지원, 구축 비용"},{"term":"가용성","desc":"장애 없이 지속적으로 사용 가능한 정도"},{"term":"상호 호환성","desc":"운영체제, 개발 도구 등과 함께 쓸 수 있는 정도"}],"memo":"DBMS 고르는 기준은 가성호기구(가용성, 성능, 상호 호환성, 기술 지원, 구축 비용)."}},{"id":"written-2020-1-2-19","no":19,"unit":"소프트웨어 설계","q":"HIPO(Hierarchy Input Process Output)에 대한 설명으로 거리가 먼 것은?","choices":["상향식 소프트웨어 개발을 위한 문서화 도구이다.","HIPO 차트 종류에는 가시적 도표, 총체적 도표, 세부적 도표가 있다.","기능과 자료의 의존 관계를 동시에 표현할 수 있다.","보기 쉽고 이해하기 쉽다."],"ans":1,"rate":71,"wiki":[{"title":"HIPO","url":"https://itwiki.kr/w/HIPO"}],"exp":{"concept":"HIPO(Hierarchy Input Process Output)는 시스템의 기능을 위에서 아래로 계층적으로 나누고 각 기능의 입력, 처리, 출력을 표로 정리하는 문서화 도구다. 하향식 개발을 위한 도구이며 가시적 도표, 총체적 도표, 세부적 도표 세 종류로 이루어진다.","choices":[{"verdict":"정답","why":"HIPO는 기능을 위에서 아래로 나누어 가는 하향식 소프트웨어 개발을 위한 문서화 도구이므로, 상향식이라는 설명이 틀려 정답이다."},{"verdict":"오답","why":"HIPO 차트는 가시적 도표(Visual Table of Contents), 총체적 도표(Overview Diagram), 세부적 도표(Detail Diagram)로 구성된다."},{"verdict":"오답","why":"입력, 처리, 출력을 함께 나타내므로 기능과 자료의 의존 관계를 동시에 표현할 수 있다."},{"verdict":"오답","why":"계층 구조와 표 형식이라 보기 쉽고 이해하기 쉬우며, 유지보수에도 유리하다."}],"keywords":[{"term":"HIPO","desc":"하향식 개발을 위한 계층적 입력-처리-출력 문서화 도구"},{"term":"가시적 도표","desc":"시스템 기능을 계층 구조로 보여 주는 도표, 입력·처리·출력 없음"},{"term":"총체적 도표","desc":"입력, 처리, 출력에 대한 전반적인 정보 제공"},{"term":"세부적 도표","desc":"총체적 도표의 기능을 구성하는 기본 요소를 상세히 기술"}],"memo":"Hierarchy는 위에서 아래로 내려가는 계층이므로 HIPO는 하향식."}},{"id":"written-2020-1-2-20","no":20,"unit":"소프트웨어 설계","q":"객체지향 분석 방법론 중 E-R 다이어그램을 사용하여 객체의 행위를 모델링하며, 객체식별, 구조 식별, 주체 정의, 속성 및 관계 정의, 서비스 정의 등의 과정으로 구성되는 것은?","choices":["Coad와 Yourdon 방법","Booch 방법","Jacobson 방법","Wirfs-Brocks 방법"],"ans":1,"rate":68,"exp":{"concept":"객체지향 분석 방법론마다 쓰는 도구와 절차가 다르다. Coad와 Yourdon 방법은 E-R 다이어그램을 사용해 객체의 행위를 모델링하며, 객체 식별, 구조 식별, 주체 정의, 속성과 관계 정의, 서비스 정의 순서로 진행한다.","choices":[{"verdict":"정답","why":"Coad와 Yourdon 방법은 E-R 다이어그램으로 객체의 행위를 모델링하고 객체 식별, 구조 식별, 주체 정의, 속성 및 관계 정의, 서비스 정의 과정으로 구성되므로 정답이다."},{"verdict":"오답","why":"Booch 방법은 미시적(Micro) 개발 프로세스와 거시적(Macro) 개발 프로세스를 모두 사용하며 클래스와 객체를 분석·식별하는 방법이다."},{"verdict":"오답","why":"Jacobson 방법은 유스케이스(Use Case)를 강조해 사용자와 시스템의 상호작용을 중심으로 분석하는 방법이다."},{"verdict":"오답","why":"Wirfs-Brock 방법은 분석과 설계를 구분하지 않고 고객 명세서를 평가해 설계 작업까지 연속적으로 수행하는 방법이다."}],"keywords":[{"term":"Coad-Yourdon","desc":"E-R 다이어그램으로 객체 행위 모델링"},{"term":"Booch","desc":"미시적·거시적 개발 프로세스 사용"},{"term":"Jacobson","desc":"유스케이스 중심"},{"term":"Rumbaugh","desc":"객체 모형, 동적 모형, 기능 모형으로 분석"}],"memo":"E-R이면 Coad-Yourdon, 유스케이스면 Jacobson, 미시·거시면 Booch, 3가지 모형이면 Rumbaugh."}},{"id":"written-2020-1-2-21","no":21,"unit":"소프트웨어 개발","q":"정렬된 N개의 데이터를 처리하는데 O(N log₂N)의 시간이 소요되는 정렬 알고리즘은?","choices":["선택정렬","삽입정렬","버블정렬","합병정렬"],"ans":4,"rate":59,"wiki":[{"title":"정렬","url":"https://itwiki.kr/w/정렬"}],"exp":{"concept":"시간 복잡도는 데이터가 N개일 때 처리 시간이 얼마나 늘어나는지를 나타낸다. 선택, 삽입, 버블 정렬은 평균 O(N²)이고, 합병 정렬은 데이터를 반씩 나눠 정렬한 뒤 합치므로 항상 O(N log₂N)이다.","choices":[{"verdict":"오답","why":"선택 정렬은 매번 남은 데이터 중 최솟값을 찾아 앞으로 옮기므로 O(N²)이다."},{"verdict":"오답","why":"삽입 정렬은 평균과 최악이 O(N²)이며, 이미 정렬된 데이터라면 비교만 하고 지나가므로 O(N)이다."},{"verdict":"오답","why":"버블 정렬은 인접한 두 값을 비교·교환하는 과정을 반복하므로 O(N²)이다."},{"verdict":"정답","why":"합병 정렬(Merge Sort)은 데이터를 절반으로 나누고 정렬된 두 부분을 합치는 과정을 반복해 O(N log₂N)이 걸리므로 정답이다."}],"keywords":[{"term":"합병 정렬","desc":"분할 후 병합, 항상 O(N log₂N)"},{"term":"퀵 정렬","desc":"피벗 기준 분할, 평균 O(N log₂N), 최악 O(N²)"},{"term":"힙 정렬","desc":"힙 구조 이용, O(N log₂N)"},{"term":"선택·삽입·버블 정렬","desc":"평균 O(N²)"}],"memo":"나누고 합치는(분할 정복) 정렬은 N log N, 하나씩 비교해 옮기는 정렬은 N²으로 기억한다."}},{"id":"written-2020-1-2-22","no":22,"unit":"소프트웨어 개발","q":"White Box Testing 에 대한 설명으로 옳지 않은 것은?","choices":["Base Path Testing, Boundary Value Analysis가 대표적인 기법이다.","Source Code 의 모든 문장을 한번 이상 수행함으로서 진행된다.","모듈 안의 작동을 직접 관찰 할 수 있다.","산출물의 각 기능별로 적절한 프로그램의 제어구조에 따라 선택, 반복 등의 부분들을 수행함으로써 논리적 경로를 점검한다."],"ans":1,"rate":59,"wiki":[{"title":"화이트박스 테스트","url":"https://itwiki.kr/w/화이트박스 테스트"}],"exp":{"concept":"화이트박스 테스트는 프로그램 내부 소스 코드를 보면서 모든 문장, 조건, 경로가 제대로 실행되는지 확인하는 테스트다. 기초 경로 검사, 제어 구조 검사(조건, 루프, 데이터 흐름 검사)가 대표 기법이다. 경계값 분석은 내부를 보지 않고 입력과 출력만 보는 블랙박스 기법이다.","choices":[{"verdict":"정답","why":"기초 경로 검사(Base Path Testing)는 화이트박스 기법이 맞지만, 경계값 분석(Boundary Value Analysis)은 블랙박스 테스트 기법이므로 옳지 않은 설명이라 정답이다."},{"verdict":"오답","why":"화이트박스 테스트는 소스 코드의 모든 문장을 한 번 이상 수행해 보는 방식으로 진행된다."},{"verdict":"오답","why":"내부 소스 코드를 보며 테스트하므로 모듈 안의 작동을 직접 관찰할 수 있다."},{"verdict":"오답","why":"프로그램의 제어 구조에 따라 선택, 반복 등의 부분을 수행해 논리적 경로를 점검하는 것이 화이트박스 테스트다."}],"keywords":[{"term":"화이트박스 테스트","desc":"내부 소스 코드를 보며 논리 경로를 검사"},{"term":"화이트박스 기법","desc":"기초 경로 검사, 조건 검사, 루프 검사, 데이터 흐름 검사"},{"term":"블랙박스 기법","desc":"동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사"}],"memo":"경계값과 동치 분할은 입력값만 보면 되니 블랙박스, 경로와 루프는 코드를 봐야 하니 화이트박스."}},{"id":"written-2020-1-2-23","no":23,"unit":"소프트웨어 개발","q":"소프트웨어 품질 측정을 위해 개발자 관점에서 고려해야 할 항목으로 거리가 먼 것은?","choices":["정확성","무결성","사용성","간결성"],"ans":4,"rate":61,"exp":{"concept":"소프트웨어 품질 요소(McCall)는 정확성, 신뢰성, 효율성, 무결성, 사용 용이성(사용성), 유지보수성, 유연성, 시험 용이성, 이식성, 재사용성, 상호 운용성 등이다. 간결성은 이 품질 요소 목록에 들어가지 않는다.","choices":[{"verdict":"오답","why":"정확성은 사용자의 요구 기능을 충족시키는 정도로, 품질 측정 항목에 속한다."},{"verdict":"오답","why":"무결성은 허용되지 않은 사용이나 자료 변경을 막는 정도로, 품질 측정 항목에 속한다."},{"verdict":"오답","why":"사용성은 사용자가 쉽게 사용할 수 있는 정도로, 품질 측정 항목에 속한다."},{"verdict":"정답","why":"간결성은 소프트웨어 품질 요소로 분류되는 항목이 아니므로 거리가 멀어 정답이다."}],"keywords":[{"term":"정확성(Correctness)","desc":"사용자 요구 기능을 충족하는 정도"},{"term":"무결성(Integrity)","desc":"허용되지 않은 사용이나 변경을 막는 정도"},{"term":"사용성(Usability)","desc":"쉽게 배우고 사용할 수 있는 정도"},{"term":"유지보수성(Maintainability)","desc":"오류를 쉽게 찾아 수정할 수 있는 정도"}],"memo":"품질 요소는 정확성, 신뢰성, 효율성, 무결성, 사용성처럼 '~성'이지만 간결성은 목록에 없다는 점이 함정이다."}},{"id":"written-2020-1-2-24","no":24,"unit":"소프트웨어 개발","q":"인터페이스 구현 검증도구 중 아래에서 설명하는 것은?\n<img src=\"data/img/eip_written_20200606_024.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["xUnit","STAF","FitNesse","RubyNode"],"ans":2,"rate":59,"exp":{"concept":"인터페이스 구현 검증 도구는 모듈 사이 연결이 제대로 동작하는지 자동으로 테스트하는 도구다. 지문은 서비스 호출, 컴포넌트 재사용 등 다양한 환경을 지원하고, 분산 환경 각 대상에 데몬을 띄워 테스트를 수행·통합·자동화한다고 설명하므로 STAF다.","choices":[{"verdict":"오답","why":"xUnit은 JUnit, CppUnit, NUnit처럼 Java, C++, .Net 등 다양한 언어를 지원하는 단위 테스트 프레임워크다."},{"verdict":"정답","why":"STAF는 서비스 호출, 컴포넌트 재사용 등 다양한 환경을 지원하고, 분산 환경 각 테스트 대상에서 데몬을 사용해 테스트를 수행·통합·자동화하는 검증 도구이므로 정답이다."},{"verdict":"오답","why":"FitNesse는 웹 기반으로 테스트 케이스를 설계하고 실행하며 결과를 확인할 수 있게 지원하는 테스트 프레임워크다."},{"verdict":"오답","why":"RubyNode는 인터페이스 구현 검증 도구로 출제 범위에서 다루는 표준 도구가 아니다."}],"keywords":[{"term":"xUnit","desc":"여러 언어를 지원하는 단위 테스트 프레임워크"},{"term":"STAF","desc":"분산 환경에서 데몬을 사용해 테스트 수행·통합·자동화"},{"term":"FitNesse","desc":"웹 기반 테스트 케이스 설계·실행·결과 확인"},{"term":"NTAF","desc":"FitNesse의 장점과 STAF의 장점을 통합한 NHN의 자동화 프레임워크"},{"term":"Selenium","desc":"다양한 브라우저와 개발 언어를 지원하는 웹 애플리케이션 테스트 프레임워크"}],"memo":"분산 환경과 데몬이 보이면 STAF, 웹 기반 테스트 케이스 설계면 FitNesse, 단위 테스트면 xUnit."}},{"id":"written-2020-1-2-25","no":25,"unit":"소프트웨어 개발","q":"EAI(Enterprise Application Integration)의 구축 유형으로 옳지 않은 것은?","choices":["Point-to-Point","Hub&Spoke","Message Bus","Tree"],"ans":4,"rate":67,"exp":{"concept":"EAI(Enterprise Application Integration)는 기업 안의 여러 애플리케이션을 서로 연결해 정보를 주고받게 하는 솔루션이다. 구축 유형은 Point-to-Point, Hub & Spoke, Message Bus, Hybrid 네 가지다. Tree는 EAI 구축 유형이 아니다.","choices":[{"verdict":"오답","why":"Point-to-Point는 애플리케이션끼리 1대1로 직접 연결하는 가장 기본적인 EAI 구축 유형이다."},{"verdict":"오답","why":"Hub & Spoke는 가운데 허브 시스템을 거쳐 데이터를 전송하는 중앙 집중형 EAI 구축 유형이다."},{"verdict":"오답","why":"Message Bus는 애플리케이션 사이에 미들웨어(버스)를 두어 처리하는 EAI 구축 유형이다."},{"verdict":"정답","why":"Tree는 EAI 구축 유형이 아니므로 정답이다. 네 번째 유형은 Hub & Spoke와 Message Bus를 섞은 Hybrid다."}],"keywords":[{"term":"Point-to-Point","desc":"1대1 직접 연결, 변경과 재사용이 어려움"},{"term":"Hub & Spoke","desc":"허브를 통한 중앙 집중 연결, 허브 장애 시 전체 영향"},{"term":"Message Bus","desc":"미들웨어 버스를 두어 확장성이 높음"},{"term":"Hybrid","desc":"그룹 내는 Hub & Spoke, 그룹 간은 Message Bus"}],"memo":"EAI 유형은 점(Point), 바퀴(Hub & Spoke), 버스(Bus), 혼합(Hybrid). 나무(Tree)는 없다."}},{"id":"written-2020-1-2-26","no":26,"unit":"소프트웨어 개발","q":"다음 트리를 전위 순회(preorder traversal)한 결과는?\n<img src=\"data/img/eip_written_20200606_026.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["+*AB/*CDE","AB/C*D*E+","A/B*C*D+E","+**/ABCDE"],"ans":4,"rate":71,"wiki":[{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"전위 순회(Preorder)는 루트, 왼쪽, 오른쪽 순서로 노드를 방문한다. 그림 트리는 루트 +의 왼쪽 자식이 *, 그 왼쪽이 다시 *, 그 왼쪽이 /이고 / 아래에 A와 B가 있다. 오른쪽 자식은 아래쪽부터 C, D, E다. 수식 트리를 전위 순회하면 연산자가 앞에 오는 전위 표기식이 나온다.","choices":[{"verdict":"오답","why":"+*AB/*CDE는 그림 트리의 어떤 순회 결과와도 맞지 않는다. 전위 순회는 + 다음에 왼쪽 자식 *, 그 다음 다시 *, / 순으로 내려가야 한다."},{"verdict":"오답","why":"AB/C*D*E+는 왼쪽, 오른쪽, 루트 순서로 방문한 후위 순회 결과다."},{"verdict":"오답","why":"A/B*C*D+E는 왼쪽, 루트, 오른쪽 순서로 방문한 중위 순회 결과로, 원래 수식과 같다."},{"verdict":"정답","why":"루트 +, 왼쪽 *, 다시 왼쪽 *, 다시 왼쪽 /, 그 아래 A, B를 방문한 뒤 돌아오며 오른쪽 C, D, E를 차례로 방문하므로 +**/ABCDE가 되어 정답이다."}],"keywords":[{"term":"전위 순회(Preorder)","desc":"루트, 왼쪽, 오른쪽 순서, 결과는 전위 표기식"},{"term":"중위 순회(Inorder)","desc":"왼쪽, 루트, 오른쪽 순서, 결과는 일반 수식"},{"term":"후위 순회(Postorder)","desc":"왼쪽, 오른쪽, 루트 순서, 결과는 후위 표기식"}],"memo":"루트를 언제 방문하느냐로 구분한다. 앞(전위), 가운데(중위), 뒤(후위)."}},{"id":"written-2020-1-2-27","no":27,"unit":"소프트웨어 개발","q":"인터페이스 보안을 위해 네트워크 영역에 적용될 수 있는 솔루션과 거리가 먼 것은?","choices":["IPSec","SMTP","SSL","S-HTTP"],"ans":2,"rate":70,"wiki":[{"title":"이메일 프로토콜","url":"https://itwiki.kr/w/이메일 프로토콜"}],"exp":{"concept":"인터페이스 보안은 모듈이나 시스템 사이에 오가는 데이터를 보호하는 것이다. 네트워크 영역에서는 IPSec, SSL(TLS), S-HTTP처럼 전송 구간을 암호화하는 프로토콜을 쓴다. SMTP는 메일을 보내는 프로토콜일 뿐 보안 솔루션이 아니다.","choices":[{"verdict":"오답","why":"IPSec은 네트워크 계층(IP)에서 패킷을 암호화하고 인증하는 보안 프로토콜로, 네트워크 영역 보안 솔루션이다."},{"verdict":"정답","why":"SMTP(Simple Mail Transfer Protocol)는 전자우편을 전송하는 응용 계층 프로토콜로, 보안 솔루션이 아니므로 정답이다."},{"verdict":"오답","why":"SSL(Secure Sockets Layer)은 응용 계층과 전송 계층 사이에서 데이터를 암호화하는 보안 프로토콜이다."},{"verdict":"오답","why":"S-HTTP(Secure HTTP)는 웹에서 클라이언트와 서버 사이에 오가는 메시지를 암호화하는 보안 프로토콜이다."}],"keywords":[{"term":"IPSec","desc":"IP 계층에서 암호화와 인증을 제공"},{"term":"SSL/TLS","desc":"전송 계층 위에서 데이터를 암호화"},{"term":"S-HTTP","desc":"웹 메시지를 암호화하는 HTTP 확장"},{"term":"SMTP","desc":"메일 전송 프로토콜, 보안 기능 없음"}],"memo":"앞에 S(Secure)나 Sec이 붙으면 보안, SMTP의 S는 Simple이다."}},{"id":"written-2020-1-2-28","no":28,"unit":"소프트웨어 개발","q":"평가 점수에 따른 성적부여는 다음 표와 같다. 이를 구현한 소프트웨어를 경계값 분석 기법으로 테스트 하고자 할 때 다음 중 테스트 케이스의 입력 값으로 옳지 않은 것은?\n<img src=\"data/img/eip_written_20200606_028.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["59","80","90","101"],"ans":3,"rate":70,"exp":{"concept":"경계값 분석은 오류가 경계 부근에서 많이 생긴다는 점을 이용해 경계값과 그 바로 바깥 값을 테스트 입력으로 쓰는 블랙박스 기법이다. 표의 구간은 0~59(C), 60~79(B), 80~100(A)이므로 경계값은 -1, 0, 59, 60, 79, 80, 100, 101 같은 값이다. 90은 A 구간의 한가운데라 경계값이 아니다.","choices":[{"verdict":"오답","why":"59는 C 구간의 상한이자 B 구간 하한 60의 바로 아래 값이므로 경계값 테스트 입력으로 알맞다."},{"verdict":"오답","why":"80은 A 구간의 하한 경계값이므로 테스트 입력으로 알맞다."},{"verdict":"정답","why":"90은 80~100 구간 한가운데 값이라 경계값이 아니므로 옳지 않아 정답이다. 이런 대표값은 동치 분할 기법에서 쓴다."},{"verdict":"오답","why":"101은 최댓값 100의 바로 바깥 값으로, 범위를 벗어난 입력을 확인하는 경계값 테스트 입력이다."}],"keywords":[{"term":"경계값 분석","desc":"구간의 경계값과 그 바로 안팎 값을 테스트"},{"term":"동치 분할 검사","desc":"입력을 같은 결과를 내는 구간으로 나눠 각 구간의 대표값을 테스트"},{"term":"블랙박스 테스트","desc":"내부 구조를 보지 않고 입력과 출력으로 기능을 확인"}],"memo":"경계값은 구간 끝(59, 60, 79, 80, 100)과 범위 밖 한 칸(-1, 101), 가운데 값은 동치 분할."}},{"id":"written-2020-1-2-29","no":29,"unit":"소프트웨어 개발","q":"반정규화(Denormalization) 유형중 중복 테이블을 추가하는 방법에 해당하지 않는 것은?","choices":["빌드 테이블의 추가","집계 테이블의 추가","진행 테이블의 추가","특정 부분만을 포함하는 테이블의 추가"],"ans":1,"rate":47,"exp":{"concept":"반정규화는 성능을 위해 정규화된 테이블을 일부러 합치거나 중복을 허용하는 것이다. 중복 테이블을 추가하는 방법에는 집계 테이블 추가, 진행 테이블 추가, 특정 부분만을 포함하는 테이블 추가가 있다.","choices":[{"verdict":"정답","why":"빌드 테이블의 추가는 반정규화의 중복 테이블 추가 방법에 해당하지 않으므로 정답이다."},{"verdict":"오답","why":"집계 테이블의 추가는 합계, 평균 같은 집계 데이터를 위한 테이블을 따로 만들고 원본이 바뀔 때 트리거로 갱신하는 방법이다."},{"verdict":"오답","why":"진행 테이블의 추가는 이력 관리 등 진행 상황을 관리하려고 테이블을 추가하는 방법이다."},{"verdict":"오답","why":"특정 부분만을 포함하는 테이블의 추가는 데이터가 많은 테이블에서 자주 쓰는 일부 컬럼이나 행만 모아 별도 테이블을 만드는 방법이다."}],"keywords":[{"term":"반정규화(Denormalization)","desc":"성능 향상을 위해 정규화 원칙을 일부 위배하고 중복 허용"},{"term":"집계 테이블","desc":"집계 데이터를 별도 보관, 트리거로 갱신"},{"term":"진행 테이블","desc":"이력 관리 목적의 테이블"},{"term":"특정 부분만 포함하는 테이블","desc":"자주 쓰는 일부만 모은 테이블"}],"memo":"중복 테이블 추가는 집계, 진행, 특정 부분 세 가지. 빌드라는 말은 없다."}},{"id":"written-2020-1-2-30","no":30,"unit":"소프트웨어 개발","q":"ISO/IEC 9126의 소프트웨어 품질 특성 중 기능성(Functionlity)의 하위 특성으로 옳지 않은 것은?","choices":["학습성","적합성","정확성","보안성"],"ans":1,"rate":62,"exp":{"concept":"ISO/IEC 9126은 소프트웨어 품질 특성을 기능성, 신뢰성, 사용성, 효율성, 유지보수성, 이식성 6가지로 정의한 국제 표준이다. 기능성의 하위 특성은 적합성, 정확성, 상호 운용성, 보안성, 준수성이다. 학습성은 사용성의 하위 특성이다.","choices":[{"verdict":"정답","why":"학습성은 사용자가 쉽게 배울 수 있는 정도로, 기능성이 아니라 사용성의 하위 특성이므로 정답이다."},{"verdict":"오답","why":"적합성은 지정된 작업에 알맞은 기능을 제공하는 정도로, 기능성의 하위 특성이다."},{"verdict":"오답","why":"정확성은 기대한 결과를 정확하게 산출하는 정도로, 기능성의 하위 특성이다."},{"verdict":"오답","why":"보안성은 허가되지 않은 접근을 막는 정도로, 기능성의 하위 특성이다."}],"keywords":[{"term":"기능성 하위 특성","desc":"적합성, 정확성, 상호 운용성, 보안성, 준수성"},{"term":"사용성 하위 특성","desc":"이해성, 학습성, 운용성, 친밀성"},{"term":"ISO/IEC 9126 품질 특성","desc":"기능성, 신뢰성, 사용성, 효율성, 유지보수성, 이식성"}],"memo":"배우기 쉬운지(학습성)는 쓰기 편한지(사용성)의 문제다."}},{"id":"written-2020-1-2-31","no":31,"unit":"소프트웨어 개발","q":"다음 트리의 차수(degree)와 단말 노드(terminal node)의 수는?\n<img src=\"data/img/eip_written_20200606_031.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["차수: 4, 단말 노드: 4","차수: 2, 단말 노드: 4","차수: 4, 단말 노드: 8","차수: 2, 단말 노드: 8"],"ans":2,"rate":62,"wiki":[{"title":"트리","url":"https://itwiki.kr/w/트리"}],"exp":{"concept":"트리의 차수는 각 노드가 가진 자식 수 중 가장 큰 값이고, 단말 노드는 자식이 하나도 없는 노드다. 그림에서 A의 자식은 B, C 2개, B는 D 1개, C는 E, F 2개, E는 G, H 2개다. 최댓값이 2이므로 차수는 2, 자식이 없는 D, F, G, H 4개가 단말 노드다.","choices":[{"verdict":"오답","why":"단말 노드 4개는 맞지만, 한 노드의 자식이 최대 2개이므로 차수는 4가 아니라 2다. 4는 트리의 레벨 수와 같은 값이다."},{"verdict":"정답","why":"자식 수의 최댓값이 2이므로 차수는 2, 자식이 없는 노드는 D, F, G, H로 4개이므로 정답이다."},{"verdict":"오답","why":"차수는 2이고, 8은 단말 노드 수가 아니라 전체 노드 수다."},{"verdict":"오답","why":"차수 2는 맞지만 8은 전체 노드 수이며 단말 노드는 4개다."}],"keywords":[{"term":"노드의 차수(Degree)","desc":"한 노드가 가진 자식(서브트리)의 수"},{"term":"트리의 차수","desc":"노드 차수 중 최댓값"},{"term":"단말 노드(Terminal Node, Leaf)","desc":"자식이 없는 노드, 차수가 0"},{"term":"트리의 깊이(Depth)","desc":"루트부터 가장 깊은 노드까지의 레벨 수"}],"memo":"차수는 가장 많은 자식 수, 단말은 맨 끝 잎사귀. 전체 노드 수나 레벨 수와 헷갈리지 않는다."}},{"id":"written-2020-1-2-32","no":32,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM)의 기술 요소가 아닌 것은?","choices":["크랙 방지 기술","정책 관리 기술","암호화 기술","방화벽 기술"],"ans":4,"rate":71,"wiki":[{"title":"DRM","url":"https://itwiki.kr/w/DRM"}],"exp":{"concept":"DRM(Digital Rights Management)은 디지털 콘텐츠를 허가된 사람만 허가된 방식으로 쓰게 하는 저작권 보호 기술이다. 기술 요소에는 암호화, 키 관리, 암호화 파일 생성, 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증이 있다. 방화벽은 네트워크 보안 장비라 DRM 기술 요소가 아니다.","choices":[{"verdict":"오답","why":"크랙 방지(Tamper Resistance) 기술은 크랙에 의한 콘텐츠 사용 방지 기술로, DRM 기술 요소다."},{"verdict":"오답","why":"정책 관리 기술은 라이선스 발급, 사용 권한 등에 대한 정책을 정의하고 관리하는 DRM 기술 요소다."},{"verdict":"오답","why":"암호화 기술은 콘텐츠와 라이선스를 암호화하고 전자 서명을 할 수 있게 하는 DRM 기술 요소다."},{"verdict":"정답","why":"방화벽(Firewall)은 내부 네트워크와 외부 네트워크 사이에서 허가되지 않은 트래픽을 차단하는 네트워크 보안 시스템으로, DRM 기술 요소가 아니므로 정답이다."}],"keywords":[{"term":"DRM","desc":"디지털 콘텐츠의 저작권을 보호하고 사용을 통제하는 기술"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 배포 가능한 단위로 묶음"},{"term":"클리어링 하우스(Clearing House)","desc":"저작권 사용 권한, 라이선스 발급, 결제 관리"},{"term":"크랙 방지","desc":"크랙으로 콘텐츠를 불법 사용하는 것을 막는 기술"}],"memo":"DRM은 콘텐츠 자체를 지키는 기술(암호화, 키, 정책, 크랙 방지), 방화벽은 네트워크를 지키는 장비."}},{"id":"written-2020-1-2-33","no":33,"unit":"소프트웨어 개발","q":"소프트 웨어 테스트에서 오류의 80%는 전체 모듈의 20% 내에서 발견된다는 법칙은?","choices":["Brooks의 법칙","Boehm의 법칙","Pareto의 법칙","Jackson의 법칙"],"ans":3,"rate":67,"wiki":[{"title":"파레토 원칙","url":"https://itwiki.kr/w/파레토 원칙"},{"title":"브룩스의 법칙","url":"https://itwiki.kr/w/브룩스의 법칙"}],"exp":{"concept":"파레토 법칙은 결과의 80%가 원인의 20%에서 나온다는 법칙이다. 테스트에 적용하면 오류의 80%가 전체 모듈의 20% 안에서 발견된다는 뜻이 되며, 테스트 원리 중 결함 집중과 같은 내용이다.","choices":[{"verdict":"오답","why":"브룩스(Brooks)의 법칙은 일정이 지연된 프로젝트에 인력을 더 투입하면 오히려 더 지연된다는 법칙이다."},{"verdict":"오답","why":"보헴(Boehm)은 COCOMO 비용 산정 모형과 나선형 모형을 제안한 학자로, 80/20 오류 분포를 뜻하는 법칙과 관계없다."},{"verdict":"정답","why":"파레토(Pareto)의 법칙은 오류의 80%가 전체 모듈의 20%에서 발견된다는 법칙이므로 정답이다."},{"verdict":"오답","why":"잭슨(Jackson)은 자료 구조 중심 설계 방법으로 알려진 학자이며, 오류 분포에 관한 법칙은 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"파레토 법칙","desc":"오류의 80%는 20% 모듈에서 발견"},{"term":"브룩스 법칙","desc":"지연된 프로젝트에 인력 추가 시 더 지연"},{"term":"살충제 패러독스","desc":"같은 테스트를 반복하면 새 결함을 찾지 못함"},{"term":"결함 집중","desc":"결함은 소수 모듈에 몰려 있다는 테스트 원리"}],"memo":"80대 20이 나오면 파레토, 사람을 더 넣어 더 늦어지면 브룩스."}},{"id":"written-2020-1-2-34","no":34,"unit":"소프트웨어 개발","q":"소프트웨어 형상 관리의 의미로 적절한 것은?","choices":["비용에 관한 사항을 효율적으로 관리하는 것","개발 과정의 변경 사항을 관리하는 것","테스트 과정에서 소프트웨어를 통합하는 것","개발 인력을 관리하는 것"],"ans":2,"rate":69,"wiki":[{"title":"형상 관리","url":"https://itwiki.kr/w/형상 관리"}],"exp":{"concept":"소프트웨어 형상 관리(SCM, Software Configuration Management)는 개발 과정에서 생기는 소스 코드, 문서 등의 변경 사항을 체계적으로 관리하는 활동이다. 누가 언제 무엇을 바꿨는지 기록하고 버전을 관리한다.","choices":[{"verdict":"오답","why":"비용을 효율적으로 관리하는 것은 프로젝트 비용 관리이며 형상 관리의 의미가 아니다."},{"verdict":"정답","why":"형상 관리는 개발 과정에서 발생하는 소프트웨어의 변경 사항을 관리하는 것이므로 정답이다."},{"verdict":"오답","why":"테스트 과정에서 소프트웨어를 통합하는 것은 통합 테스트에 관한 설명이다."},{"verdict":"오답","why":"개발 인력을 관리하는 것은 프로젝트 인력 관리(조직 관리)에 관한 설명이다."}],"keywords":[{"term":"형상 관리","desc":"소프트웨어 변경 사항을 체계적으로 관리"},{"term":"형상 관리 절차","desc":"형상 식별, 형상 통제, 형상 감사, 형상 기록"},{"term":"형상 관리 도구","desc":"Git, SVN, CVS 같은 버전 관리 도구"}],"memo":"형상 관리는 곧 변경 관리. 절차는 식별, 통제, 감사, 기록."}},{"id":"written-2020-1-2-35","no":35,"unit":"소프트웨어 개발","q":"알고리즘 시간복잡도 O(1)이 의미하는 것은?","choices":["컴퓨터 처리가 불가","알고리즘 입력 데이터 수가 한 개","알고리즘 수행시간이 입력 데이터 수와 관계없이 일정","알고리즘 길이가 입력 데이터보다 작음"],"ans":3,"rate":79,"wiki":[{"title":"점근적 표기법","url":"https://itwiki.kr/w/점근적 표기법"}],"exp":{"concept":"빅오 표기법의 O(1)은 입력 데이터가 몇 개든 처리 시간이 늘 일정하다는 뜻이다. 배열에서 인덱스로 원소 하나를 꺼내는 것처럼, 데이터가 10개든 100만 개든 한 번에 끝나는 경우다.","choices":[{"verdict":"오답","why":"O(1)은 처리 불가가 아니라 가장 빠른 상수 시간을 의미한다."},{"verdict":"오답","why":"O(1)의 1은 입력 데이터 수가 아니라 수행 시간이 상수라는 뜻이다."},{"verdict":"정답","why":"O(1)은 알고리즘의 수행 시간이 입력 데이터 수와 관계없이 일정하다는 의미이므로 정답이다."},{"verdict":"오답","why":"알고리즘 길이와 입력 데이터 크기를 비교하는 개념이 아니다."}],"keywords":[{"term":"O(1)","desc":"상수 시간, 입력 크기와 무관"},{"term":"O(log₂N)","desc":"로그 시간, 이진 탐색"},{"term":"O(N)","desc":"선형 시간, 순차 탐색"},{"term":"O(N²)","desc":"제곱 시간, 버블·선택·삽입 정렬"}],"memo":"O(1)의 1은 개수가 아니라 상수. 데이터가 늘어도 시간이 그대로다."}},{"id":"written-2020-1-2-36","no":36,"unit":"소프트웨어 개발","q":"소스코드 품질분석 도구 중 정적분석 도구가 아닌 것은?","choices":["pmd","cppcheck","valMeter","checkstyle"],"ans":3,"rate":61,"exp":{"concept":"소스 코드 품질 분석 도구는 실행하지 않고 코드만 보고 분석하는 정적 분석 도구와, 실행하면서 분석하는 동적 분석 도구로 나뉜다. 정적 분석 도구로는 pmd, cppcheck, checkstyle, SonarQube, ccm, cobertura가 있고, 동적 분석 도구로는 Avalanche, Valgrind가 있다.","choices":[{"verdict":"오답","why":"pmd는 자바 등의 소스 코드에서 미사용 변수, 최적화되지 않은 코드 같은 결함을 찾는 정적 분석 도구다."},{"verdict":"오답","why":"cppcheck는 C와 C++ 코드의 메모리 누수, 오버플로 등을 분석하는 정적 분석 도구다."},{"verdict":"정답","why":"valMeter는 출제 범위에서 정적 분석 도구로 분류되지 않으므로 정답이다."},{"verdict":"오답","why":"checkstyle은 자바 코드가 코딩 표준을 따르는지 검사하는 정적 분석 도구다."}],"keywords":[{"term":"정적 분석 도구","desc":"pmd, cppcheck, checkstyle, SonarQube, ccm, cobertura"},{"term":"동적 분석 도구","desc":"Avalanche, Valgrind"},{"term":"정적 분석","desc":"코드를 실행하지 않고 분석"},{"term":"동적 분석","desc":"코드를 실행하며 메모리 누수 등을 분석"}],"memo":"동적 도구는 Avalanche와 Valgrind 두 개만 외우고, pmd·cppcheck·checkstyle은 정적으로 묶는다."}},{"id":"written-2020-1-2-37","no":37,"unit":"소프트웨어 개발","q":"검증 검사 기법 중 개발자의 장소에서 사용자가 개발자 앞에서 행하는 기법이며, 일반적으로 통제된 환경에서 사용자와 개발자가 함께 확인하면서 수행되는 검사는?","choices":["동치 분할 검사","형상 검사","알파 검사","베타 검사"],"ans":3,"rate":72,"wiki":[{"title":"인수 테스트","url":"https://itwiki.kr/w/인수 테스트"}],"exp":{"concept":"인수 테스트 중 알파 검사와 베타 검사는 장소와 통제 여부로 구분한다. 알파 검사는 개발자의 장소에서 사용자가 개발자 앞에서 통제된 환경으로 수행한다. 베타 검사는 개발자 없이 사용자의 실제 환경에서 수행한다.","choices":[{"verdict":"오답","why":"동치 분할 검사는 입력 데이터를 같은 결과를 내는 영역으로 나눠 대표값으로 테스트하는 블랙박스 기법이다."},{"verdict":"오답","why":"형상 검사는 구성 요소, 목록, 유지보수에 필요한 사항이 표현되었는지 확인하는 검사다."},{"verdict":"정답","why":"알파 검사는 개발자의 장소에서 사용자가 개발자 앞에서 통제된 환경으로 함께 확인하며 수행하는 검사이므로 정답이다."},{"verdict":"오답","why":"베타 검사는 개발자 없이 여러 사용자가 실제 사용 환경에서 수행하고 발견한 오류를 개발자에게 알리는 검사다."}],"keywords":[{"term":"알파 검사","desc":"개발자 장소, 개발자 앞, 통제된 환경"},{"term":"베타 검사","desc":"사용자 장소, 개발자 없음, 실제 환경"},{"term":"인수 테스트","desc":"사용자가 요구사항 충족 여부를 확인하는 최종 테스트"}],"memo":"알파는 개발자가 지켜보는 자리에서, 베타는 개발자 없이 사용자 현장에서."}},{"id":"written-2020-1-2-38","no":38,"unit":"소프트웨어 개발","q":"하향식 통합에 있어서 모듈 간의 통합 시험을 위해 일시적으로 필요한 조건만을 가지고 임시로 제공되는 시험용 모듈을 무엇이라고 하는가?","choices":["Stub","Driver","Procedure","Function"],"ans":1,"rate":79,"wiki":[{"title":"통합 테스트","url":"https://itwiki.kr/w/통합 테스트"}],"exp":{"concept":"하향식 통합은 상위 모듈부터 아래로 내려가며 통합한다. 이때 아직 만들어지지 않은 하위 모듈 자리를 임시로 채우는 가짜 모듈이 스텁(Stub)이다. 반대로 상향식 통합에서 상위 모듈 대신 하위 모듈을 호출해 주는 임시 모듈은 드라이버(Driver)다.","choices":[{"verdict":"정답","why":"스텁(Stub)은 하향식 통합에서 아직 없는 하위 모듈을 대신해 필요한 조건만 갖춘 임시 시험용 모듈이므로 정답이다."},{"verdict":"오답","why":"드라이버(Driver)는 상향식 통합에서 상위 모듈 역할을 대신해 테스트 대상을 호출하는 임시 모듈이다."},{"verdict":"오답","why":"프로시저(Procedure)는 특정 작업을 수행하는 코드 묶음을 가리키는 일반 용어로, 통합 시험용 임시 모듈을 뜻하지 않는다."},{"verdict":"오답","why":"함수(Function)는 값을 받아 처리하고 결과를 반환하는 코드 단위로, 통합 시험용 임시 모듈을 뜻하지 않는다."}],"keywords":[{"term":"스텁(Stub)","desc":"하향식 통합에서 하위 모듈을 대신하는 임시 모듈"},{"term":"드라이버(Driver)","desc":"상향식 통합에서 상위 모듈을 대신하는 임시 모듈"},{"term":"하향식 통합","desc":"상위 모듈부터 깊이 우선 또는 넓이 우선으로 통합"}],"memo":"하향식은 아래가 비어 스텁, 상향식은 위가 비어 드라이버. 하스상드로 외운다."}},{"id":"written-2020-1-2-39","no":39,"unit":"소프트웨어 개발","q":"SW 패키징 도구 활용 시 고려 사항과 거리가 먼 것은?","choices":["패키징 시 사용자에게 배포되는 SW이므로 보안을 고려한다.","사용자 편의성을 위한 복합성 및 비효율성 문제를 고려한다.","보안상 단일 기종에서만 사용할 수 있도록 해야 한다.","제품 SW 종류에 적합한 암호화 알고리즘을 적용한다."],"ans":3,"rate":91,"exp":{"concept":"SW 패키징은 개발이 끝난 소프트웨어를 사용자에게 배포할 수 있는 형태로 묶는 작업이다. 이때 보안, 사용자 편의성에 따른 복잡성과 비효율성, 다양한 이기종 콘텐츠 및 단말기와의 연동, 제품 SW 종류에 적합한 암호화 알고리즘 적용을 고려해야 한다.","choices":[{"verdict":"오답","why":"패키징된 SW는 사용자에게 배포되므로 반드시 보안을 고려해야 한다는 설명은 옳다."},{"verdict":"오답","why":"사용자 편의성을 위한 복잡성과 비효율성 문제를 고려해야 한다는 설명은 옳다."},{"verdict":"정답","why":"패키징 시에는 다양한 이기종 콘텐츠와 단말기에 배포될 수 있도록 연동을 고려해야 하므로, 단일 기종에서만 사용하도록 해야 한다는 설명은 틀려 정답이다."},{"verdict":"오답","why":"제품 SW 종류에 적합한 암호화 알고리즘을 적용해야 한다는 설명은 옳다."}],"keywords":[{"term":"SW 패키징","desc":"개발 완료된 SW를 배포 가능한 형태로 묶는 작업"},{"term":"패키징 고려 사항","desc":"보안, 편의성 대비 복잡성과 비효율성, 이기종 연동, 암호화 알고리즘"},{"term":"DRM 연동","desc":"패키징 도구에서 저작권 보호를 위해 함께 적용하는 기술"}],"memo":"패키징은 여러 기종에서 쓸 수 있게(이기종 연동) 만드는 것이 원칙. 단일 기종은 오답 단골이다."}},{"id":"written-2020-1-2-40","no":40,"unit":"소프트웨어 개발","q":"외계인코드(Alien Code)에 대한 설명으로 옳은 것은?","choices":["프로그램의 로직이 복잡하여 이해하기 어려운 프로그램을 의미한다.","아주 오래되거나 참고문서 또는 개발자가 없어 유지보수 작업이 어려운 프로그램을 의미한다.","오류가 없어 디버깅 과정이 필요 없는 프로그램을 의미한다.","사용자가 직접 작성한 프로그램을 의미한다."],"ans":2,"rate":81,"wiki":[{"title":"외계인 코드","url":"https://itwiki.kr/w/외계인 코드"}],"exp":{"concept":"외계인 코드(Alien Code)는 아주 오래되었거나, 참고할 문서나 개발자가 없어서 아무도 내용을 몰라 유지보수가 매우 어려운 프로그램을 말한다. 외계인이 쓴 것처럼 알아볼 수 없다는 뜻이다.","choices":[{"verdict":"오답","why":"로직이 복잡해 이해하기 어려운 프로그램은 스파게티 코드(Spaghetti Code)에 가까운 설명이다."},{"verdict":"정답","why":"외계인 코드는 아주 오래되거나 참고 문서 또는 개발자가 없어 유지보수 작업이 어려운 프로그램이므로 정답이다."},{"verdict":"오답","why":"오류가 없어 디버깅이 필요 없는 프로그램을 가리키는 말이 아니다."},{"verdict":"오답","why":"사용자가 직접 작성한 프로그램을 가리키는 말이 아니다."}],"keywords":[{"term":"외계인 코드(Alien Code)","desc":"오래되거나 문서·개발자가 없어 유지보수가 어려운 코드"},{"term":"스파게티 코드(Spaghetti Code)","desc":"로직이 얽혀 이해하기 어려운 코드"},{"term":"레거시 시스템(Legacy System)","desc":"오래되었지만 여전히 사용 중인 기존 시스템"}],"memo":"외계인 코드는 만든 사람도 문서도 없는 코드, 스파게티 코드는 꼬여 있는 코드."}},{"id":"written-2020-1-2-41","no":41,"unit":"데이터베이스 구축","q":"SQL 의 분류 중 DDL에 해당하지 않는 것은?","choices":["UPDATE","ALTER","DROP","CREATE"],"ans":1,"rate":66,"wiki":[{"title":"DDL","url":"https://itwiki.kr/w/DDL"}],"exp":{"concept":"SQL은 기능에 따라 DDL, DML, DCL로 나뉜다. DDL(Data Definition Language)은 테이블 같은 구조를 만들고 바꾸고 없애는 CREATE, ALTER, DROP이다. UPDATE는 저장된 데이터 값을 바꾸는 DML이다.","choices":[{"verdict":"정답","why":"UPDATE는 테이블에 저장된 데이터를 수정하는 DML(데이터 조작어)이므로 DDL에 해당하지 않아 정답이다."},{"verdict":"오답","why":"ALTER는 테이블 등 객체의 구조를 변경하는 DDL이다."},{"verdict":"오답","why":"DROP은 테이블 등 객체를 삭제하는 DDL이다."},{"verdict":"오답","why":"CREATE는 테이블, 뷰, 인덱스 등 객체를 생성하는 DDL이다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP, TRUNCATE, 구조 정의"},{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE, 데이터 조작"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK, 권한과 제어"}],"memo":"구조는 DDL(CREATE, ALTER, DROP), 내용물은 DML(SELECT, INSERT, UPDATE, DELETE)."}},{"id":"written-2020-1-2-42","no":42,"unit":"데이터베이스 구축","q":"다음 두 릴레이션에서 외래키로 사용된 것은? (단 밑줄 친 속성은 기본키이다.)\n<img src=\"data/img/eip_written_20200606_042.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["수강번호","과목번호","학번","과목명"],"ans":2,"rate":86,"wiki":[{"title":"데이터베이스 키","url":"https://itwiki.kr/w/데이터베이스 키"}],"exp":{"concept":"외래키는 다른 릴레이션의 기본키를 참조하는 속성이다. 과목(과목번호, 과목명)의 기본키는 과목번호이고, 수강(수강번호, 학번, 과목번호, 학기)의 기본키는 수강번호다. 수강 릴레이션의 과목번호가 과목 릴레이션의 기본키 과목번호를 참조하므로 외래키다.","choices":[{"verdict":"오답","why":"수강번호는 수강 릴레이션의 기본키다."},{"verdict":"정답","why":"과목번호는 수강 릴레이션에 있으면서 과목 릴레이션의 기본키를 참조하므로 외래키이며 정답이다."},{"verdict":"오답","why":"학번은 제시된 두 릴레이션 중 어느 쪽의 기본키도 참조하지 않으므로, 이 문제에서 외래키로 볼 근거가 없다."},{"verdict":"오답","why":"과목명은 과목 릴레이션의 일반 속성이며 다른 릴레이션을 참조하지 않는다."}],"keywords":[{"term":"외래키(Foreign Key)","desc":"다른 릴레이션의 기본키를 참조하는 속성"},{"term":"기본키(Primary Key)","desc":"튜플을 유일하게 식별하는 후보키 중 선택된 키"},{"term":"참조 무결성","desc":"외래키 값은 참조하는 기본키 값이거나 NULL이어야 함"}],"memo":"두 테이블에 똑같이 나오고 한쪽에서는 기본키인 속성이 외래키다."}},{"id":"written-2020-1-2-43","no":43,"unit":"데이터베이스 구축","q":"데이터 무결성 제약조건 중 “개체 무결성 제약”조건에 대한 설명으로 맞는 것은?","choices":["릴레이션 내의 튜플들이 각 속성의 도메인에 지정된 값만을 가져야 한다.","기본키에 속해 있는 애트리뷰트는 널값이나 중복값을 가\n질 수 없다.","릴레이션은 참조할 수 없는 외래키 값을 가질 수 없다.","외래키 값은 참조 릴레이션의 기본키 값과 동일해야 한다."],"ans":2,"rate":69,"exp":{"concept":"무결성 제약 조건은 데이터의 정확성을 지키는 규칙이다. 개체 무결성은 기본키를 이루는 속성이 NULL이거나 중복될 수 없다는 규칙이다. 주민등록번호가 비어 있거나 두 사람이 같으면 사람을 구분할 수 없는 것과 같다.","choices":[{"verdict":"오답","why":"각 속성 값이 도메인에 지정된 값만 가져야 한다는 것은 도메인 무결성이다."},{"verdict":"정답","why":"기본키에 속한 속성은 널 값이나 중복 값을 가질 수 없다는 것이 개체 무결성이므로 정답이다."},{"verdict":"오답","why":"참조할 수 없는 외래키 값을 가질 수 없다는 것은 참조 무결성이다."},{"verdict":"오답","why":"외래키 값이 참조 릴레이션의 기본키 값과 같아야 한다는 것은 참조 무결성에 관한 설명이다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 NULL 불가, 중복 불가"},{"term":"참조 무결성","desc":"외래키는 참조 릴레이션의 기본키 값이거나 NULL"},{"term":"도메인 무결성","desc":"속성 값은 정의된 도메인 안의 값만 허용"}],"memo":"개체는 기본키, 참조는 외래키, 도메인은 값의 범위로 짝지어 외운다."}},{"id":"written-2020-1-2-44","no":44,"unit":"데이터베이스 구축","q":"뷰(view)에 대한 설명으로 옳지 않은 것은?","choices":["뷰는 CREATE 문을 사용하여 정의한다.","뷰는 데이터의 논리적 독립성을 제공한다.","뷰를 제거할 때에는 DROP 문을 사용한다.","뷰는 저장장치 내에 물리적으로 존재한다."],"ans":4,"rate":81,"wiki":[{"title":"데이터베이스 뷰","url":"https://itwiki.kr/w/데이터베이스 뷰"}],"exp":{"concept":"뷰(View)는 기본 테이블에서 필요한 부분만 골라 보여 주는 가상 테이블이다. 실제 데이터는 기본 테이블에만 있고, 뷰는 정의(질의문)만 저장되어 있어 물리적으로 존재하지 않는다.","choices":[{"verdict":"오답","why":"뷰는 CREATE VIEW 문으로 정의한다."},{"verdict":"오답","why":"뷰를 쓰면 기본 테이블 구조가 바뀌어도 응용 프로그램이 영향을 덜 받으므로 논리적 독립성을 제공한다."},{"verdict":"오답","why":"뷰를 제거할 때는 DROP VIEW 문을 사용한다."},{"verdict":"정답","why":"뷰는 물리적으로 저장되지 않는 가상 테이블이므로, 저장장치 내에 물리적으로 존재한다는 설명은 틀려 정답이다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 독립성 제공, 데이터 보안, 사용자 관점 단순화"},{"term":"뷰의 단점","desc":"정의 변경 불가(ALTER로 수정 불가), 삽입·삭제·갱신에 제약"}],"memo":"뷰는 창문(View)처럼 보여 주기만 할 뿐 데이터를 따로 담지 않는다."}},{"id":"written-2020-1-2-45","no":45,"unit":"데이터베이스 구축","q":"다음 SQL 문의 실행 결과는?\n<img src=\"data/img/eip_written_20200606_045.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["10,000","15,000","20,000","25,000"],"ans":4,"rate":95,"exp":{"concept":"괄호 안 하위 질의가 먼저 실행되고 그 결과를 바깥 질의 조건에 쓴다. 하위 질의는 도서 테이블에서 책명이 '자료구조'인 책번호 222를 돌려준다. 바깥 질의는 도서가격 테이블에서 책번호가 222인 행의 가격 25,000을 출력한다.","choices":[{"verdict":"오답","why":"10,000은 책번호 333(컴퓨터구조)의 가격이다."},{"verdict":"오답","why":"15,000은 도서 테이블에 없는 책번호 444의 가격이다."},{"verdict":"오답","why":"20,000은 책번호 111(운영체제)의 가격이다."},{"verdict":"정답","why":"하위 질의 결과 책번호 222를 조건으로 도서가격 테이블에서 찾으면 가격이 25,000이므로 정답이다."}],"keywords":[{"term":"하위 질의(Subquery)","desc":"다른 질의 안에 들어 있는 질의, 먼저 실행됨"},{"term":"WHERE 절","desc":"조건에 맞는 행만 고름"},{"term":"= 비교와 하위 질의","desc":"하위 질의 결과가 한 행일 때 =로 비교 가능"}],"memo":"하위 질의부터 풀고(자료구조 → 222), 그 값을 바깥 질의에 넣는다(222 → 25,000)."}},{"id":"written-2020-1-2-46","no":46,"unit":"데이터베이스 구축","q":"데이터베이스의 논리적 설계(logical design) 단계에서 수행하는 작업이 아닌 것은?","choices":["레코드 집중의 분석 및 설계","논리적 데이터베이스 구조로 매핑(mapping)","트랜잭션 인터페이스 설계","스키마의 평가 및 정제"],"ans":1,"rate":44,"wiki":[{"title":"데이터 모델링","url":"https://itwiki.kr/w/데이터 모델링"}],"exp":{"concept":"데이터베이스 설계는 요구 조건 분석, 개념적 설계, 논리적 설계, 물리적 설계, 구현 순서로 진행한다. 논리적 설계는 특정 DBMS의 데이터 모델(예: 관계형 테이블)로 바꾸는 단계로, 매핑, 트랜잭션 인터페이스 설계, 스키마 평가와 정제를 한다. 레코드 집중(클러스터링) 설계는 저장 방식을 다루는 물리적 설계의 일이다.","choices":[{"verdict":"정답","why":"레코드 집중의 분석 및 설계는 데이터를 저장장치에 어떻게 모아 둘지 정하는 물리적 설계 작업이므로 논리적 설계 작업이 아니라 정답이다."},{"verdict":"오답","why":"개념 스키마를 논리적 데이터베이스 구조로 매핑하는 것은 논리적 설계의 핵심 작업이다."},{"verdict":"오답","why":"트랜잭션 인터페이스 설계는 논리적 설계 단계에서 수행한다."},{"verdict":"오답","why":"스키마의 평가 및 정제는 논리적 설계 단계에서 수행한다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, 트랜잭션 모델링"},{"term":"논리적 설계","desc":"DBMS 데이터 모델로 매핑, 트랜잭션 인터페이스 설계, 스키마 평가·정제"},{"term":"물리적 설계","desc":"저장 레코드 양식, 레코드 집중, 접근 경로, 인덱스 설계"}],"memo":"저장장치, 레코드 집중, 접근 경로, 인덱스처럼 하드웨어 냄새가 나면 물리적 설계."}},{"id":"written-2020-1-2-47","no":47,"unit":"데이터베이스 구축","q":"이행적 함수 종속 관계를 의미하는 것은?","choices":["A→B이고 B→C 일 때, A→C를 만족하는 관계","A→B이고 B→C 일 때, C→A를 만족하는 관계","A→B이고 B→C 일 때, B→A를 만족하는 관계","A→B이고 B→C 일 때, C→B를 만족하는 관계"],"ans":1,"rate":87,"wiki":[{"title":"함수적 종속성","url":"https://itwiki.kr/w/함수적 종속성"}],"exp":{"concept":"함수 종속 A→B는 A 값이 정해지면 B 값이 하나로 정해진다는 뜻이다. 이행적 함수 종속은 A→B이고 B→C일 때 결과적으로 A→C가 성립하는 관계다. 3정규형은 이 이행적 함수 종속을 없애는 단계다.","choices":[{"verdict":"정답","why":"A→B이고 B→C일 때 A→C가 성립하는 관계가 이행적 함수 종속이므로 정답이다."},{"verdict":"오답","why":"C→A는 이행 관계에서 도출되지 않는다."},{"verdict":"오답","why":"B→A는 이행적 함수 종속의 정의와 관계없다."},{"verdict":"오답","why":"C→B는 이행적 함수 종속의 정의와 관계없다."}],"keywords":[{"term":"함수 종속(A→B)","desc":"A 값이 B 값을 유일하게 결정"},{"term":"이행적 함수 종속","desc":"A→B, B→C이면 A→C"},{"term":"3정규형(3NF)","desc":"이행적 함수 종속을 제거한 정규형"}],"memo":"도미노처럼 A가 B를 넘기고 B가 C를 넘기면 A가 C를 넘긴 셈이다. 이행 종속 제거는 3NF."}},{"id":"written-2020-1-2-48","no":48,"unit":"데이터베이스 구축","q":"하나의 애트리뷰트가 가질 수 있는 원자값들의 집합을 의미하는 것은?","choices":["도메인","튜플","엔티티","다형성"],"ans":1,"rate":61,"exp":{"concept":"도메인(Domain)은 한 속성이 가질 수 있는 원자값들의 집합이다. 예를 들어 성별 속성의 도메인은 {남, 여}이고, 학년 속성의 도메인은 {1, 2, 3, 4}다.","choices":[{"verdict":"정답","why":"도메인은 하나의 애트리뷰트가 가질 수 있는 원자값들의 집합이므로 정답이다."},{"verdict":"오답","why":"튜플(Tuple)은 릴레이션의 한 행으로, 하나의 개체에 대한 속성 값들의 모임이다."},{"verdict":"오답","why":"엔티티(Entity)는 현실 세계에서 저장할 가치가 있는 대상(사람, 사물, 사건 등)이다."},{"verdict":"오답","why":"다형성(Polymorphism)은 하나의 메시지에 객체마다 다르게 반응하는 객체지향 개념으로 데이터베이스 구조 용어가 아니다."}],"keywords":[{"term":"도메인","desc":"한 속성이 가질 수 있는 원자값들의 집합"},{"term":"튜플","desc":"릴레이션의 행, 카디널리티는 튜플 수"},{"term":"애트리뷰트","desc":"릴레이션의 열, 차수(Degree)는 속성 수"}],"memo":"도메인은 속성 값의 허용 범위(울타리)라고 생각한다."}},{"id":"written-2020-1-2-49","no":49,"unit":"데이터베이스 구축","q":"STUDENT 테이블에 독일어과 학생 50명, 중국어과 학생 30명, 영어영문학과 학생 50명의 정보가 저장되어 있을 때, 다음 두 SQL문의 실행 결과 튜플 수는? (단, DEPT 컬럼은 학과명)\n<img src=\"data/img/eip_written_20200606_049.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["ⓐ 3, ⓑ 3","ⓐ 50, ⓑ 3","ⓐ 130, ⓑ 3","ⓐ 130, ⓑ 130"],"ans":3,"rate":82,"exp":{"concept":"SELECT는 조건이 없으면 모든 행을 그대로 가져오고, DISTINCT를 붙이면 중복된 값을 하나만 남긴다. STUDENT에는 50 + 30 + 50 = 130명이 있으므로 ⓐ는 130행이다. ⓑ는 DEPT 값 중 중복을 제거해 독일어과, 중국어과, 영어영문학과 3행이 된다.","choices":[{"verdict":"오답","why":"ⓐ는 DISTINCT가 없어 모든 학생의 학과명이 나오므로 3이 아니라 130이다."},{"verdict":"오답","why":"ⓐ의 결과는 한 학과 인원 50이 아니라 전체 학생 수 130이다."},{"verdict":"정답","why":"ⓐ는 전체 130행, ⓑ는 중복을 제거한 학과 3개이므로 정답이다."},{"verdict":"오답","why":"ⓑ는 DISTINCT로 중복을 제거하므로 130이 아니라 3이다."}],"keywords":[{"term":"DISTINCT","desc":"검색 결과에서 중복 행을 제거"},{"term":"ALL","desc":"중복을 포함해 모두 출력, 생략 시 기본값"},{"term":"튜플 수","desc":"결과 릴레이션의 행 개수"}],"memo":"DISTINCT가 없으면 사람 수만큼, 있으면 종류 수만큼 나온다."}},{"id":"written-2020-1-2-50","no":50,"unit":"데이터베이스 구축","q":"관계대수 연산에서 두 릴레이션이 공통으로 가지고 있는 속성을 이용하여 두 개의 릴레이션을 하나로 합쳐서 새로운 릴레이션을 만드는 연산은?","choices":["⋈","⊃","π","σ"],"ans":1,"rate":76,"wiki":[{"title":"관계대수","url":"https://itwiki.kr/w/관계대수"}],"exp":{"concept":"관계대수에서 조인(Join, ⋈)은 두 릴레이션이 공통으로 가진 속성을 기준으로 값이 같은 튜플끼리 연결해 하나의 새 릴레이션을 만드는 연산이다.","choices":[{"verdict":"정답","why":"⋈는 조인 기호로, 공통 속성을 이용해 두 릴레이션을 하나로 합치는 연산이므로 정답이다."},{"verdict":"오답","why":"⊃는 관계대수의 연산자 기호가 아니다. 관계대수의 디비전(Division)은 ÷로 표기한다."},{"verdict":"오답","why":"π(Project)는 릴레이션에서 지정한 속성(열)만 뽑아 내는 연산이다."},{"verdict":"오답","why":"σ(Select)는 릴레이션에서 조건을 만족하는 튜플(행)만 골라 내는 연산이다."}],"keywords":[{"term":"σ (Select)","desc":"조건에 맞는 행 선택, 수평 연산"},{"term":"π (Project)","desc":"지정한 열 추출, 수직 연산"},{"term":"⋈ (Join)","desc":"공통 속성으로 두 릴레이션 결합"},{"term":"÷ (Division)","desc":"다른 릴레이션의 속성 값을 모두 가진 튜플 추출"}],"memo":"⋈는 두 릴레이션을 나비 넥타이처럼 묶는 모양으로 기억한다. σ는 행, π는 열."}},{"id":"written-2020-1-2-51","no":51,"unit":"데이터베이스 구축","q":"트랜잭션의 특성 중 다음 설명에 해당하는 것은?\n<img src=\"data/img/eip_written_20200606_051.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Durability","Share","Consistency","Atomicity"],"ans":4,"rate":68,"wiki":[{"title":"트랜잭션 특성","url":"https://itwiki.kr/w/트랜잭션 특성"}],"exp":{"concept":"트랜잭션은 데이터베이스에서 한꺼번에 처리되어야 하는 작업 묶음이다. 트랜잭션의 4가지 특성은 원자성, 일관성, 독립성(격리성), 영속성(지속성)이다. 지문의 '모두 반영되든지 전혀 반영되지 않아야 한다'는 원자성을 설명한다. 계좌 이체에서 출금만 되고 입금이 안 되는 일이 없어야 하는 것과 같다.","choices":[{"verdict":"오답","why":"Durability(영속성)는 성공적으로 완료된 트랜잭션의 결과는 시스템이 고장 나도 영구히 반영되어야 한다는 특성이다."},{"verdict":"오답","why":"Share는 트랜잭션의 특성(ACID)에 속하지 않는다."},{"verdict":"오답","why":"Consistency(일관성)는 트랜잭션이 실행을 마치면 언제나 일관성 있는 데이터베이스 상태로 변환되어야 한다는 특성이다."},{"verdict":"정답","why":"Atomicity(원자성)는 트랜잭션의 연산이 모두 반영되거나 전혀 반영되지 않아야 한다는 All or Nothing 특성이므로 정답이다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"모두 반영되거나 전혀 반영되지 않음, Commit과 Rollback"},{"term":"일관성(Consistency)","desc":"실행 후에도 데이터베이스가 일관된 상태 유지"},{"term":"독립성(Isolation)","desc":"실행 중인 트랜잭션에 다른 트랜잭션이 끼어들 수 없음"},{"term":"영속성(Durability)","desc":"완료된 결과는 영구히 반영"}],"memo":"ACID 중 All or Nothing은 Atomicity. A는 All의 A로 연결하면 빨리 떠오른다."}},{"id":"written-2020-1-2-52","no":52,"unit":"데이터베이스 구축","q":"분산 데이터베이스 목표 중 “데이터베이스의 분산된 물리적 환경에서 특정 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생해도 데이터 무결성이 보장된다”는 것과 관계있는 것은?","choices":["장애 투명성","병행 투명성","위치 투명성","중복 투명성"],"ans":1,"rate":67,"wiki":[{"title":"분산 데이터베이스","url":"https://itwiki.kr/w/분산 데이터베이스"}],"exp":{"concept":"분산 데이터베이스는 여러 지역에 흩어진 데이터베이스를 하나처럼 쓰게 한다. 이를 위해 사용자가 분산 사실을 의식하지 않아도 되는 여러 투명성을 목표로 한다. 특정 지역 시스템이나 네트워크에 장애가 생겨도 무결성이 보장되는 것은 장애 투명성이다.","choices":[{"verdict":"정답","why":"장애 투명성(Failure Transparency)은 특정 지역의 시스템이나 네트워크에 장애가 발생해도 데이터 무결성이 보장되는 것이므로 정답이다."},{"verdict":"오답","why":"병행 투명성(Concurrency Transparency)은 여러 트랜잭션이 동시에 수행되어도 결과의 일관성이 유지되는 것이다."},{"verdict":"오답","why":"위치 투명성(Location Transparency)은 데이터의 물리적 위치를 몰라도 논리적인 이름만으로 접근할 수 있는 것이다."},{"verdict":"오답","why":"중복 투명성(Replication Transparency)은 같은 데이터가 여러 곳에 중복되어 있어도 사용자는 하나의 데이터만 존재하는 것처럼 사용하는 것이다."}],"keywords":[{"term":"위치 투명성","desc":"데이터 위치를 몰라도 논리적 이름으로 접근"},{"term":"중복 투명성","desc":"중복 저장되어 있어도 하나처럼 사용"},{"term":"병행 투명성","desc":"동시 수행해도 결과 일관성 유지"},{"term":"장애 투명성","desc":"장애가 발생해도 무결성 보장"}],"memo":"분산 DB 투명성은 위중병장(위치, 중복, 병행, 장애). 장애라는 단어가 나오면 장애 투명성."}},{"id":"written-2020-1-2-53","no":53,"unit":"데이터베이스 구축","q":"데이터베이스 시스템에서 삽입, 갱신, 삭제 등의 이벤트가 발생할 때마다 관련 작업이 자동으로 수행되는 절차형 SQL은?","choices":["트리거(trigger)","무결성(integrity)","잠금(lock)","복귀(rollback)"],"ans":1,"rate":81,"exp":{"concept":"트리거(Trigger)는 데이터베이스에 삽입, 갱신, 삭제 같은 이벤트가 생길 때마다 자동으로 실행되도록 저장해 둔 절차형 SQL이다. 문이 열리면 자동으로 불이 켜지는 센서 조명과 비슷하다.","choices":[{"verdict":"정답","why":"트리거는 삽입, 갱신, 삭제 등의 이벤트가 발생할 때마다 관련 작업이 자동으로 수행되는 절차형 SQL이므로 정답이다."},{"verdict":"오답","why":"무결성(Integrity)은 데이터의 정확성과 일관성을 뜻하는 성질로, 절차형 SQL이 아니다."},{"verdict":"오답","why":"잠금(Lock)은 병행 제어를 위해 트랜잭션이 사용하는 데이터에 다른 트랜잭션의 접근을 막는 기법이다."},{"verdict":"오답","why":"복귀(Rollback)는 트랜잭션이 비정상 종료되었을 때 수행한 작업을 취소하는 명령이다."}],"keywords":[{"term":"트리거","desc":"이벤트 발생 시 자동 실행되는 절차형 SQL"},{"term":"프로시저(Procedure)","desc":"호출해서 실행하는 절차형 SQL, 반환값 없어도 됨"},{"term":"사용자 정의 함수","desc":"값을 반드시 반환하는 절차형 SQL"}],"memo":"방아쇠(Trigger)를 당기듯 이벤트가 일어나면 자동 발사된다."}},{"id":"written-2020-1-2-54","no":54,"unit":"데이터베이스 구축","q":"참조 무결성을 유지하기 위하여 DROP문에서 부모 테이블의 항목 값을 삭제할 경우 자동적으로 자식 테이블의 해당 레코드를 삭제하기 위한 옵션은?","choices":["CLUSTER","CASCADE","SET-NULL","RESTRICTED"],"ans":2,"rate":78,"wiki":[{"title":"참조 무결성 제약","url":"https://itwiki.kr/w/참조 무결성 제약"}],"exp":{"concept":"참조 무결성은 자식 테이블의 외래키가 부모 테이블의 없는 값을 가리키지 않게 하는 규칙이다. 부모 테이블의 행을 삭제할 때 자식 테이블의 관련 행도 자동으로 함께 삭제하려면 CASCADE 옵션을 쓴다.","choices":[{"verdict":"오답","why":"CLUSTER는 데이터를 물리적으로 모아 저장하는 저장 구조와 관련된 용어로, 참조 무결성 삭제 옵션이 아니다."},{"verdict":"정답","why":"CASCADE는 부모 테이블의 값을 삭제하면 이를 참조하는 자식 테이블의 레코드도 연쇄적으로 삭제하는 옵션이므로 정답이다."},{"verdict":"오답","why":"SET NULL은 부모 값이 삭제되면 자식 테이블의 해당 외래키 값을 NULL로 바꾸는 옵션이다."},{"verdict":"오답","why":"RESTRICT는 다른 테이블이 참조하고 있으면 부모 값의 삭제를 거부하는 옵션이다."}],"keywords":[{"term":"CASCADE","desc":"부모 삭제 시 자식도 연쇄 삭제"},{"term":"SET NULL","desc":"부모 삭제 시 자식 외래키를 NULL로 변경"},{"term":"RESTRICT","desc":"참조 중이면 삭제 거부"},{"term":"NO ACTION","desc":"참조 무결성을 위반하는 변경을 허용하지 않음"}],"memo":"CASCADE는 폭포처럼 연쇄적으로 같이 삭제된다는 뜻."}},{"id":"written-2020-1-2-55","no":55,"unit":"데이터베이스 구축","q":"DML에 해당하는 SQL 명령으로만 나열된 것은?","choices":["DELETE, UPDATE, CREATE, ALTER","INSERT, DELETE, UPDATE, DROP","SELECT, INSERT, DELETE, UPDATE","SELECT, INSERT, DELETE, ALTER"],"ans":3,"rate":77,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"DML(Data Manipulation Language)은 테이블에 저장된 데이터를 조회하고 넣고 지우고 바꾸는 명령이다. SELECT, INSERT, DELETE, UPDATE 네 가지다. CREATE, ALTER, DROP은 구조를 다루는 DDL이다.","choices":[{"verdict":"오답","why":"CREATE와 ALTER는 DDL이므로 DML로만 나열한 것이 아니다."},{"verdict":"오답","why":"DROP은 DDL이므로 DML로만 나열한 것이 아니다."},{"verdict":"정답","why":"SELECT, INSERT, DELETE, UPDATE는 모두 DML이므로 정답이다."},{"verdict":"오답","why":"ALTER는 DDL이므로 DML로만 나열한 것이 아니다."}],"keywords":[{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DDL","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"DML은 데이터 조회와 입력·수정·삭제, 즉 SELECT, INSERT, UPDATE, DELETE 4개뿐이다."}},{"id":"written-2020-1-2-56","no":56,"unit":"데이터베이스 구축","q":"데이터 제어언어(DCL)의 기능으로 옳지 않은 것은?","choices":["데이터 보안","논리적, 물리적 데이터 구조 정의","무결성 유지","병행수행 제어"],"ans":2,"rate":62,"wiki":[{"title":"SQL","url":"https://itwiki.kr/w/SQL"}],"exp":{"concept":"DCL(Data Control Language)은 데이터를 안전하게 관리하기 위한 제어 언어다. 데이터 보안, 무결성 유지, 회복, 병행 수행 제어 기능을 맡는다. 데이터 구조를 정의하는 것은 DDL의 기능이다.","choices":[{"verdict":"오답","why":"데이터 보안은 GRANT, REVOKE로 권한을 주고 빼앗는 DCL의 기능이다."},{"verdict":"정답","why":"논리적, 물리적 데이터 구조 정의는 DDL(데이터 정의어)의 기능이므로 DCL의 기능이 아니라 정답이다."},{"verdict":"오답","why":"무결성 유지는 정확한 데이터만 유지되도록 하는 DCL의 기능이다."},{"verdict":"오답","why":"병행 수행 제어는 여러 사용자가 동시에 접근해도 일관성을 유지하게 하는 DCL의 기능이다."}],"keywords":[{"term":"DCL 기능","desc":"데이터 보안, 무결성 유지, 회복, 병행 수행 제어"},{"term":"DDL 기능","desc":"논리적·물리적 데이터 구조 정의와 변경"},{"term":"GRANT/REVOKE","desc":"권한 부여/권한 회수"}],"memo":"정의는 DDL, 조작은 DML, 보안·무결성·회복·병행 제어는 DCL."}},{"id":"written-2020-1-2-57","no":57,"unit":"데이터베이스 구축","q":"병행제어의 로킹(Locking) 단위에 대한 설명으로 옳지 않은 것은?","choices":["데이터베이스, 파일, 레코드 등은 로킹 단위가 될 수 있다.","로킹 단위가 작아지면 로킹 오버헤드가 감소한다.","로킹 단위가 작아지면 데이터베이스 공유도가 증가한다.","한꺼번에 로킹 할 수 있는 객체의 크기를 로킹 단위라고 한다."],"ans":2,"rate":70,"wiki":[{"title":"데이터베이스 로킹","url":"https://itwiki.kr/w/데이터베이스 로킹"}],"exp":{"concept":"로킹(Locking)은 한 트랜잭션이 쓰는 데이터를 다른 트랜잭션이 못 쓰게 잠그는 병행 제어 기법이다. 로킹 단위가 작으면(레코드 단위) 잠그는 횟수가 많아져 관리 부담(오버헤드)은 늘지만 동시에 쓸 수 있는 부분이 많아 공유도와 병행성은 높아진다. 단위가 크면 그 반대다.","choices":[{"verdict":"오답","why":"데이터베이스, 파일, 레코드, 필드 등은 모두 로킹 단위가 될 수 있다."},{"verdict":"정답","why":"로킹 단위가 작아지면 관리해야 할 잠금 수가 많아져 로킹 오버헤드가 증가하므로, 감소한다는 설명은 틀려 정답이다."},{"verdict":"오답","why":"로킹 단위가 작아지면 잠기는 범위가 좁아 여러 트랜잭션이 동시에 접근할 수 있으므로 공유도가 증가한다."},{"verdict":"오답","why":"한꺼번에 로킹할 수 있는 객체의 크기를 로킹 단위라고 한다."}],"keywords":[{"term":"로킹(Locking)","desc":"트랜잭션이 쓰는 데이터를 잠가 다른 접근을 막는 병행 제어 기법"},{"term":"로킹 단위 작음","desc":"오버헤드 증가, 공유도·병행성 증가"},{"term":"로킹 단위 큼","desc":"오버헤드 감소, 공유도·병행성 감소"}],"memo":"자물쇠를 잘게 나눠 많이 달수록 관리는 힘들고(오버헤드 증가) 여럿이 함께 쓰기는 좋다(공유도 증가)."}},{"id":"written-2020-1-2-58","no":58,"unit":"데이터베이스 구축","q":"E-R 모델의 표현 방법으로 옳지 않은 것은?","choices":["개체타입: 사각형","관계타입: 마름모","속성: 오각형","연결: 선"],"ans":3,"rate":89,"wiki":[{"title":"ER 다이어그램","url":"https://itwiki.kr/w/ER 다이어그램"}],"exp":{"concept":"E-R 다이어그램은 개체와 관계를 도형으로 표현한다. 개체는 사각형, 관계는 마름모, 속성은 타원, 연결은 선으로 그린다. 기본키 속성은 밑줄 친 타원, 다중값 속성은 이중 타원으로 그린다.","choices":[{"verdict":"오답","why":"개체 타입은 사각형으로 표현한다."},{"verdict":"오답","why":"관계 타입은 마름모로 표현한다."},{"verdict":"정답","why":"속성은 타원으로 표현하므로 오각형이라는 설명은 틀려 정답이다."},{"verdict":"오답","why":"개체 타입과 속성, 개체와 관계를 연결할 때는 선을 쓴다."}],"keywords":[{"term":"사각형","desc":"개체 타입"},{"term":"마름모","desc":"관계 타입"},{"term":"타원","desc":"속성, 밑줄 타원은 기본키 속성, 이중 타원은 다중값 속성"},{"term":"선","desc":"개체와 속성, 개체와 관계 연결"}],"memo":"E-R 기호: 개체 네모, 관계 마름모, 속성 동그라미(타원). 오각형은 없다."}},{"id":"written-2020-1-2-59","no":59,"unit":"데이터베이스 구축","q":"다음 설명의 ( )안에 들어갈 내용으로 적합한 것은?\n<img src=\"data/img/eip_written_20200606_059.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["중복성","최소성","참조성","동일성"],"ans":2,"rate":74,"wiki":[{"title":"데이터베이스 키","url":"https://itwiki.kr/w/데이터베이스 키"}],"exp":{"concept":"후보키는 테이블에서 각 튜플을 유일하게 구별할 수 있는 속성(들)의 집합이다. 후보키는 유일성과 최소성을 모두 만족해야 한다. 최소성은 꼭 필요한 속성만으로 구성되어 하나라도 빼면 유일성이 깨지는 성질이다.","choices":[{"verdict":"오답","why":"중복성은 후보키의 조건이 아니다. 오히려 키는 값이 중복되면 안 된다."},{"verdict":"정답","why":"후보키는 유일성과 최소성을 모두 만족해야 하므로 정답이다."},{"verdict":"오답","why":"참조성은 후보키가 만족해야 하는 성질이 아니다."},{"verdict":"오답","why":"동일성은 후보키가 만족해야 하는 성질이 아니다."}],"keywords":[{"term":"유일성","desc":"하나의 키 값으로 하나의 튜플만 식별"},{"term":"최소성","desc":"꼭 필요한 최소한의 속성으로만 구성"},{"term":"후보키","desc":"유일성과 최소성을 모두 만족"},{"term":"슈퍼키","desc":"유일성만 만족하고 최소성은 만족하지 못함"}],"memo":"후보키는 유일성과 최소성 둘 다, 슈퍼키는 유일성만."}},{"id":"written-2020-1-2-60","no":60,"unit":"데이터베이스 구축","q":"정규화 과정 중 1NF에서 2NF가 되기 위한 조건은?","choices":["1NF를 만족하는 모든 도메인이 원자 값이어야 한다.","1NF를 만족하고 키가 아닌 모든 애트리뷰트들이 기본 키에 이행적으로 함수 종속되지 않아야 한다.","1NF를 만족하고 다치 종속이 제거되어야 한다.","1NF를 만족하고 키가 아닌 모든 속성이 기본키에 대하여 완전 함수적 종속 관계를 만족해야 한다."],"ans":4,"rate":55,"exp":{"concept":"정규화는 이상 현상을 없애려고 테이블을 단계적으로 나누는 과정이다. 1NF는 모든 속성 값이 원자값, 2NF는 부분 함수 종속 제거(완전 함수 종속), 3NF는 이행적 함수 종속 제거, BCNF는 결정자가 모두 후보키, 4NF는 다치 종속 제거, 5NF는 조인 종속 제거다.","choices":[{"verdict":"오답","why":"모든 도메인이 원자 값이어야 한다는 것은 1NF가 되기 위한 조건이다."},{"verdict":"오답","why":"키가 아닌 속성이 기본키에 이행적으로 함수 종속되지 않아야 한다는 것은 2NF에서 3NF가 되기 위한 조건이다."},{"verdict":"오답","why":"다치 종속을 제거하는 것은 BCNF에서 4NF가 되기 위한 조건이다."},{"verdict":"정답","why":"키가 아닌 모든 속성이 기본키에 완전 함수 종속을 만족하도록 부분 함수 종속을 제거하는 것이 1NF에서 2NF가 되는 조건이므로 정답이다."}],"keywords":[{"term":"1NF","desc":"모든 속성 값이 원자값"},{"term":"2NF","desc":"부분 함수 종속 제거, 완전 함수 종속 만족"},{"term":"3NF","desc":"이행적 함수 종속 제거"},{"term":"BCNF","desc":"결정자가 모두 후보키"},{"term":"4NF, 5NF","desc":"다치 종속 제거, 조인 종속 제거"}],"memo":"정규화 순서는 도부이결다조(도메인 원자값, 부분 종속, 이행 종속, 결정자, 다치 종속, 조인 종속)."}},{"id":"written-2020-1-2-61","no":61,"unit":"프로그래밍 언어 활용","q":"IPv6에 대한 설명으로 틀린 것은?","choices":["128비트의 주소 공간을 제공한다.","인증 및 보안 기능을 포함하고 있다.","패킷 크기가 64Kbyte로 고정되어 있다.","IPv6 확장 헤더를 통해 네트워크 기능 확장이 용이하다."],"ans":3,"rate":80,"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"exp":{"concept":"IPv6는 IPv4 주소 부족을 해결하려고 만든 차세대 인터넷 주소 체계다. 128비트 주소를 쓰고, 인증과 보안 기능을 기본으로 갖추며, 확장 헤더로 기능을 쉽게 붙일 수 있다. 패킷 크기는 고정되어 있지 않다.","choices":[{"verdict":"오답","why":"IPv6는 128비트 주소 공간을 제공한다. IPv4는 32비트다."},{"verdict":"오답","why":"IPv6는 IPSec 기반의 인증 및 보안 기능을 포함하고 있다."},{"verdict":"정답","why":"IPv6의 패킷 크기는 64KB로 고정되어 있지 않다. 점보그램(Jumbogram) 옵션을 쓰면 64KB보다 큰 패킷도 전송할 수 있으므로 틀린 설명이라 정답이다."},{"verdict":"오답","why":"IPv6는 기본 헤더 뒤에 확장 헤더를 붙여 네트워크 기능을 쉽게 확장할 수 있다."}],"keywords":[{"term":"IPv6","desc":"128비트 주소, 16비트씩 8부분을 16진수로 표기"},{"term":"IPv4","desc":"32비트 주소, 8비트씩 4부분을 10진수로 표기"},{"term":"확장 헤더","desc":"IPv6 기본 헤더 뒤에 붙여 기능을 확장"},{"term":"IPv6 주소 유형","desc":"유니캐스트, 멀티캐스트, 애니캐스트"}],"memo":"IPv6는 128비트, 보안 내장, 확장 헤더. '고정'이라는 말이 나오면 의심한다."}},{"id":"written-2020-1-2-62","no":62,"unit":"프로그래밍 언어 활용","q":"C언어에서 비트 논리연산자에 해당하지 않는 것은?","choices":["^","?","&","~"],"ans":2,"rate":63,"wiki":[{"title":"BIT 연산","url":"https://itwiki.kr/w/BIT 연산"}],"exp":{"concept":"비트 연산자는 정수를 2진수로 보고 비트 단위로 계산한다. C 언어의 비트 연산자는 & (AND), | (OR), ^ (XOR), ~ (NOT), << (왼쪽 시프트), >> (오른쪽 시프트)다. ?는 조건 연산자 ? :의 일부다.","choices":[{"verdict":"오답","why":"^는 두 비트가 서로 다를 때 1이 되는 비트 XOR 연산자다."},{"verdict":"정답","why":"?는 조건 ? 값1 : 값2 형태로 쓰는 조건(삼항) 연산자의 일부이며 비트 연산자가 아니므로 정답이다."},{"verdict":"오답","why":"&는 두 비트가 모두 1일 때 1이 되는 비트 AND 연산자다."},{"verdict":"오답","why":"~는 각 비트를 반전시키는 비트 NOT 연산자다."}],"keywords":[{"term":"& | ^ ~","desc":"비트 AND, OR, XOR, NOT"},{"term":"<< >>","desc":"비트를 왼쪽, 오른쪽으로 이동하는 시프트 연산자"},{"term":"? :","desc":"조건 연산자, 조건이 참이면 앞의 값, 거짓이면 뒤의 값"}],"memo":"비트 연산자는 & | ^ ~ << >> 여섯 개. ?는 조건 연산자."}},{"id":"written-2020-1-2-63","no":63,"unit":"프로그래밍 언어 활용","q":"TCP/IP 프로토콜 중 전송계층 프로토콜은?","choices":["HTTP","SMTP","FTP","TCP"],"ans":4,"rate":65,"wiki":[{"title":"TCP/IP","url":"https://itwiki.kr/w/TCP/IP"},{"title":"SMTP","url":"https://itwiki.kr/w/SMTP"}],"exp":{"concept":"TCP/IP는 응용, 전송, 인터넷, 네트워크 액세스 4계층으로 나뉜다. 전송 계층 프로토콜은 TCP와 UDP이고, HTTP, SMTP, FTP는 응용 계층 프로토콜이다.","choices":[{"verdict":"오답","why":"HTTP는 웹 문서를 주고받는 응용 계층 프로토콜이다."},{"verdict":"오답","why":"SMTP는 전자우편을 전송하는 응용 계층 프로토콜이다."},{"verdict":"오답","why":"FTP는 파일을 전송하는 응용 계층 프로토콜이다."},{"verdict":"정답","why":"TCP는 연결형으로 신뢰성 있는 데이터 전송을 제공하는 전송 계층 프로토콜이므로 정답이다."}],"keywords":[{"term":"응용 계층","desc":"HTTP, FTP, SMTP, Telnet, DNS, SNMP"},{"term":"전송 계층","desc":"TCP(연결형, 신뢰성), UDP(비연결형, 빠름)"},{"term":"인터넷 계층","desc":"IP, ICMP, IGMP, ARP, RARP"}],"memo":"전송 계층은 TCP와 UDP 두 개만 기억하면 된다."}},{"id":"written-2020-1-2-64","no":64,"unit":"프로그래밍 언어 활용","q":"시스템에서 모듈 사이의 결합도(Coupling)에 대한 설명으로 옳은 것은?","choices":["한 모듈 내에 있는 처리요소들 사이의 기능적인 연관 정도를 나타낸다.","결합도가 높으면 시스템 구현 및 유지보수 작업이 쉽다.","모듈간의 결합도를 약하게 하면 모듈 독립성이 향상된다.","자료결합도는 내용결합도 보다 결합도가 높다."],"ans":3,"rate":67,"wiki":[{"title":"결합도","url":"https://itwiki.kr/w/결합도"}],"exp":{"concept":"결합도(Coupling)는 모듈과 모듈 사이가 얼마나 서로 의존하는지를 나타낸다. 결합도가 약할수록 모듈 독립성이 높아져 수정과 유지보수가 쉽다. 결합도는 자료, 스탬프, 제어, 외부, 공통, 내용 결합도 순으로 강해진다.","choices":[{"verdict":"오답","why":"한 모듈 내부 처리 요소들 사이의 기능적 연관 정도는 결합도가 아니라 응집도(Cohesion)의 설명이다."},{"verdict":"오답","why":"결합도가 높으면 한 모듈의 수정이 다른 모듈에 영향을 주므로 구현과 유지보수가 어려워진다."},{"verdict":"정답","why":"모듈 간 결합도를 약하게 하면 모듈 독립성이 향상되므로 정답이다."},{"verdict":"오답","why":"자료 결합도는 결합도가 가장 약하고 내용 결합도가 가장 강하므로, 자료 결합도가 더 높다는 설명은 틀렸다."}],"keywords":[{"term":"결합도","desc":"모듈 사이의 상호 의존 정도, 약할수록 좋음"},{"term":"응집도","desc":"모듈 내부 요소들의 기능적 연관 정도, 강할수록 좋음"},{"term":"결합도 순서(약→강)","desc":"자료, 스탬프, 제어, 외부, 공통, 내용"}],"memo":"좋은 설계는 결합도는 낮게, 응집도는 높게. 결합도 약한 순서는 자스제외공내."}},{"id":"written-2020-1-2-65","no":65,"unit":"프로그래밍 언어 활용","q":"은행가 알고리즘(Banker's Algorithm)은 교착상태의 해결 방법 중 어떤 기법에 해당하는가?","choices":["Avoidance","Detection","Prevention","Recovery"],"ans":1,"rate":65,"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"exp":{"concept":"교착 상태 해결 방법은 예방, 회피, 발견, 회복 네 가지다. 은행가 알고리즘은 자원을 할당하기 전에 시스템이 안전 상태를 유지하는지 검사해 안전할 때만 할당하는 회피(Avoidance) 기법이다. 은행이 대출 후에도 모든 고객의 인출 요구에 응할 수 있을 때만 대출해 주는 것과 같다.","choices":[{"verdict":"정답","why":"은행가 알고리즘은 안전 상태를 유지할 수 있을 때만 자원을 할당해 교착 상태를 피하는 회피(Avoidance) 기법이므로 정답이다."},{"verdict":"오답","why":"발견(Detection)은 자원 할당 그래프 등으로 교착 상태가 발생했는지 점검해 찾아내는 기법이다."},{"verdict":"오답","why":"예방(Prevention)은 상호 배제, 점유와 대기, 비선점, 환형 대기 중 하나를 미리 부정해 교착 상태가 생기지 않게 하는 기법이다."},{"verdict":"오답","why":"회복(Recovery)은 교착 상태에 빠진 프로세스를 종료하거나 자원을 선점해 교착 상태를 풀어 주는 기법이다."}],"keywords":[{"term":"예방(Prevention)","desc":"4가지 발생 조건 중 하나를 부정"},{"term":"회피(Avoidance)","desc":"안전 상태일 때만 자원 할당, 은행가 알고리즘"},{"term":"발견(Detection)","desc":"교착 상태 발생 여부를 점검"},{"term":"회복(Recovery)","desc":"프로세스 종료나 자원 선점으로 해결"}],"memo":"은행가는 위험한 대출을 피한다(Avoidance). 은행가 알고리즘은 다익스트라(Dijkstra)가 제안했다."}},{"id":"written-2020-1-2-66","no":66,"unit":"프로그래밍 언어 활용","q":"UNIX의 쉘(Shell)에 관한 설명으로 옳지 않은 것은?","choices":["명령어 해석기이다.","시스템과 사용자 간의 인터페이스를 담당한다.","여러 종류의 쉘이 있다.","프로세스, 기억장치, 입출력 관리를 수행한다."],"ans":4,"rate":62,"exp":{"concept":"UNIX는 커널과 쉘로 나뉜다. 쉘(Shell)은 사용자가 입력한 명령어를 해석해 커널에 전달하는 명령어 해석기로, 사용자와 시스템 사이의 인터페이스다. 프로세스, 기억장치, 입출력 관리는 UNIX의 핵심인 커널(Kernel)이 맡는다.","choices":[{"verdict":"오답","why":"쉘은 사용자가 입력한 명령어를 해석하는 명령어 해석기다."},{"verdict":"오답","why":"쉘은 시스템과 사용자 간의 인터페이스를 담당한다."},{"verdict":"오답","why":"쉘에는 Bourne Shell, C Shell, Korn Shell 등 여러 종류가 있다."},{"verdict":"정답","why":"프로세스, 기억장치, 입출력 관리는 커널(Kernel)의 기능이므로 쉘에 대한 설명으로 옳지 않아 정답이다."}],"keywords":[{"term":"쉘(Shell)","desc":"명령어 해석기, 사용자와 시스템 사이 인터페이스"},{"term":"커널(Kernel)","desc":"프로세스, 기억장치, 입출력, 파일 관리 등 UNIX의 핵심"},{"term":"유틸리티","desc":"편집기, 컴파일러 등 일반 사용자가 쓰는 응용 프로그램"}],"memo":"쉘은 껍데기(통역사), 커널은 알맹이(관리자). 관리 기능이 나오면 커널."}},{"id":"written-2020-1-2-67","no":67,"unit":"프로그래밍 언어 활용","q":"교착 상태 발생의 필요 충분 조건이 아닌 것은?","choices":["상호 배제(mutual exclusion)","점유와 대기(hold and wait)","환형 대기(circular wait)","선점(preemption)"],"ans":4,"rate":62,"wiki":[{"title":"교착상태","url":"https://itwiki.kr/w/교착상태"}],"exp":{"concept":"교착 상태는 여러 프로세스가 서로 상대가 가진 자원을 기다리며 영원히 멈춘 상태다. 발생 조건 네 가지는 상호 배제, 점유와 대기, 비선점, 환형 대기이며 이 네 가지가 동시에 만족되어야 교착 상태가 생긴다. 선점이 아니라 비선점이 조건이다.","choices":[{"verdict":"오답","why":"상호 배제는 한 번에 한 프로세스만 자원을 사용할 수 있다는 교착 상태 발생 조건이다."},{"verdict":"오답","why":"점유와 대기는 자원을 가진 채로 다른 자원을 기다린다는 교착 상태 발생 조건이다."},{"verdict":"오답","why":"환형 대기는 프로세스들이 원형으로 서로의 자원을 기다린다는 교착 상태 발생 조건이다."},{"verdict":"정답","why":"교착 상태 발생 조건은 다른 프로세스의 자원을 강제로 빼앗을 수 없는 비선점(Non-preemption)이다. 선점이 가능하면 자원을 빼앗아 교착 상태를 풀 수 있으므로, 선점은 발생 조건이 아니어서 정답이다."}],"keywords":[{"term":"상호 배제(Mutual Exclusion)","desc":"한 번에 한 프로세스만 자원 사용"},{"term":"점유와 대기(Hold and Wait)","desc":"자원을 가진 채 다른 자원을 기다림"},{"term":"비선점(Non-preemption)","desc":"다른 프로세스의 자원을 강제로 빼앗을 수 없음"},{"term":"환형 대기(Circular Wait)","desc":"프로세스들이 원형으로 서로의 자원을 기다림"}],"memo":"교착 상태 조건은 상점비환(상호 배제, 점유와 대기, 비선점, 환형 대기). '비'가 빠진 선점은 함정이다."}},{"id":"written-2020-1-2-68","no":68,"unit":"프로그래밍 언어 활용","q":"OSI-7계층에서 종단간 신뢰성 있고 효율적인 데이터를 전송하기 위해 오류검출과 복구, 흐름 제어를 수행하는 계층은?","choices":["전송 계층","세션 계층","표현 계층","응용 계층"],"ans":1,"rate":71,"wiki":[{"title":"OSI 7계층","url":"https://itwiki.kr/w/OSI 7계층"}],"exp":{"concept":"OSI 7계층은 물리, 데이터 링크, 네트워크, 전송, 세션, 표현, 응용 계층으로 나뉜다. 그중 전송 계층은 송신 종단과 수신 종단 사이(종단 간)에 신뢰성 있고 효율적인 전송을 위해 오류 검출과 복구, 흐름 제어를 한다.","choices":[{"verdict":"정답","why":"전송 계층은 종단 간 신뢰성 있고 효율적인 데이터 전송을 위해 오류 검출과 복구, 흐름 제어를 수행하므로 정답이다."},{"verdict":"오답","why":"세션 계층은 송수신 측 사이의 대화(세션)를 설정하고 관리하며 동기점으로 동기화를 제공한다."},{"verdict":"오답","why":"표현 계층은 데이터의 코드 변환, 암호화, 압축 등 데이터 표현 형식을 처리한다."},{"verdict":"오답","why":"응용 계층은 사용자가 네트워크에 접근할 수 있도록 응용 프로그램과 서비스를 제공한다."}],"keywords":[{"term":"전송 계층","desc":"종단 간 신뢰성, 오류 검출·복구, 흐름 제어, TCP와 UDP"},{"term":"데이터 링크 계층","desc":"인접 노드 사이의 신뢰성 있는 전송, 흐름·오류 제어"},{"term":"네트워크 계층","desc":"경로 설정(라우팅)과 패킷 전달"},{"term":"세션 계층","desc":"대화 관리와 동기점 설정"}],"memo":"종단 간(End-to-End)이라는 말이 보이면 전송 계층, 인접 노드 간이면 데이터 링크 계층."}},{"id":"written-2020-1-2-69","no":69,"unit":"프로그래밍 언어 활용","q":"IPv6의 주소체계로 거리가 먼 것은?","choices":["Unicast","Anycast","Broadcast","Multicast"],"ans":3,"rate":64,"wiki":[{"title":"IPv6","url":"https://itwiki.kr/w/IPv6"}],"exp":{"concept":"IPv6 주소는 전송 방식에 따라 유니캐스트, 멀티캐스트, 애니캐스트 세 가지로 나뉜다. IPv4에 있던 브로드캐스트는 네트워크 부하가 커서 IPv6에서는 없어지고 멀티캐스트가 그 역할을 대신한다.","choices":[{"verdict":"오답","why":"유니캐스트(Unicast)는 단일 송신자가 단일 수신자에게 전송하는 IPv6 주소 유형이다."},{"verdict":"오답","why":"애니캐스트(Anycast)는 그룹 안에서 가장 가까운 한 수신자에게 전송하는 IPv6 주소 유형이다."},{"verdict":"정답","why":"브로드캐스트(Broadcast)는 IPv4의 전송 방식이며 IPv6 주소 체계에는 없으므로 정답이다."},{"verdict":"오답","why":"멀티캐스트(Multicast)는 단일 송신자가 여러 수신자(그룹)에게 전송하는 IPv6 주소 유형이다."}],"keywords":[{"term":"유니캐스트","desc":"1대1 전송"},{"term":"멀티캐스트","desc":"1대 그룹 전송"},{"term":"애니캐스트","desc":"그룹 중 가장 가까운 하나에 전송"},{"term":"브로드캐스트","desc":"네트워크 전체에 전송, IPv4에만 있음"}],"memo":"IPv6에는 브로드캐스트가 없다. 유니, 멀티, 애니 세 가지만."}},{"id":"written-2020-1-2-70","no":70,"unit":"프로그래밍 언어 활용","q":"TCP/IP 네트워크에서 IP 주소를 MAC 주소로 변환하는 프로토콜은?","choices":["UDP","ARP","TCP","ICMP"],"ans":2,"rate":62,"wiki":[{"title":"ARP","url":"https://itwiki.kr/w/ARP"}],"exp":{"concept":"IP 주소는 논리적인 주소이고, MAC 주소는 네트워크 카드에 새겨진 물리적인 주소다. 같은 네트워크 안에서 실제로 데이터를 보내려면 상대의 MAC 주소가 필요한데, IP 주소로 MAC 주소를 알아내는 프로토콜이 ARP다.","choices":[{"verdict":"오답","why":"UDP는 비연결형으로 빠르게 데이터를 보내는 전송 계층 프로토콜이다."},{"verdict":"정답","why":"ARP(Address Resolution Protocol)는 IP 주소를 물리적 주소인 MAC 주소로 변환하는 프로토콜이므로 정답이다."},{"verdict":"오답","why":"TCP는 연결형으로 신뢰성 있는 전송을 제공하는 전송 계층 프로토콜이다."},{"verdict":"오답","why":"ICMP는 IP 패킷 처리 중 발생한 오류나 제어 메시지를 알려 주는 프로토콜이다."}],"keywords":[{"term":"ARP","desc":"IP 주소를 MAC 주소로 변환"},{"term":"RARP","desc":"MAC 주소를 IP 주소로 변환"},{"term":"ICMP","desc":"오류 보고와 제어 메시지 전달, ping에 사용"}],"memo":"ARP는 IP에서 MAC으로, 앞에 R(Reverse)이 붙은 RARP는 그 반대."}},{"id":"written-2020-1-2-71","no":71,"unit":"프로그래밍 언어 활용","q":"프로세스 상태의 종류가 아닌 것은?","choices":["Ready","Running","Request","Exit"],"ans":3,"rate":67,"wiki":[{"title":"프로세스 상태","url":"https://itwiki.kr/w/프로세스 상태"}],"exp":{"concept":"프로세스는 실행 중인 프로그램이다. 프로세스는 생성(New), 준비(Ready), 실행(Running), 대기(Waiting, Blocked), 종료(Exit, Terminated) 상태를 오가며 처리된다. Request라는 상태는 없다.","choices":[{"verdict":"오답","why":"준비(Ready)는 CPU를 할당받으려고 기다리는 프로세스 상태다."},{"verdict":"오답","why":"실행(Running)은 CPU를 할당받아 명령을 수행하는 프로세스 상태다."},{"verdict":"정답","why":"Request는 프로세스 상태의 종류가 아니므로 정답이다."},{"verdict":"오답","why":"종료(Exit)는 프로세스 실행이 끝나 할당된 자원을 반납한 프로세스 상태다."}],"keywords":[{"term":"준비(Ready)","desc":"CPU 할당을 기다리는 상태"},{"term":"실행(Running)","desc":"CPU를 차지해 실행 중인 상태"},{"term":"대기(Waiting, Blocked)","desc":"입출력 등 이벤트를 기다리는 상태"},{"term":"디스패치(Dispatch)","desc":"준비 상태 프로세스에 CPU를 할당해 실행 상태로 전이"}],"memo":"프로세스 상태는 생성, 준비, 실행, 대기, 종료. 요청(Request)은 상태가 아니다."}},{"id":"written-2020-1-2-72","no":72,"unit":"프로그래밍 언어 활용","q":"스레드(Thread)에 대한 설명으로 옳지 않은 것은?","choices":["한 개의 프로세스는 여러 개의 스레드를 가질 수 없다.","커널 스레드의 경우 운영체제에 의해 스레드를 운용한다.","사용자 스레드의 경우 사용자가 만든 라이브러리를 사용하여 스레드를 운용한다.","스레드를 사용함으로써 하드웨어, 운영체제의 성능과 응용 프로그램의 처리율을 향상시킬 수 있다."],"ans":1,"rate":77,"wiki":[{"title":"스레드","url":"https://itwiki.kr/w/스레드"}],"exp":{"concept":"스레드(Thread)는 프로세스 안에서 실제로 작업을 수행하는 실행 단위로, 경량 프로세스라고도 한다. 하나의 프로세스는 여러 스레드를 가질 수 있으며, 스레드는 프로세스의 자원을 공유하면서 병행 처리를 가능하게 한다.","choices":[{"verdict":"정답","why":"한 개의 프로세스는 여러 개의 스레드를 가질 수 있으므로(다중 스레드), 가질 수 없다는 설명은 틀려 정답이다."},{"verdict":"오답","why":"커널 수준 스레드는 운영체제의 커널이 스레드를 직접 운용한다."},{"verdict":"오답","why":"사용자 수준 스레드는 사용자가 만든 라이브러리를 사용해 스레드를 운용한다."},{"verdict":"오답","why":"스레드를 사용하면 하드웨어, 운영체제의 성능과 응용 프로그램의 처리율을 향상시킬 수 있다."}],"keywords":[{"term":"스레드","desc":"프로세스 내 실행 단위, 경량 프로세스"},{"term":"사용자 수준 스레드","desc":"사용자 라이브러리로 운용, 커널 개입 없이 전환되어 오버헤드가 적음"},{"term":"커널 수준 스레드","desc":"운영체제가 운용, 한 스레드가 대기해도 다른 스레드 실행 가능"}],"memo":"프로세스는 집, 스레드는 그 집에 사는 여러 식구. 한 집에 여러 식구가 살 수 있다."}},{"id":"written-2020-1-2-73","no":73,"unit":"프로그래밍 언어 활용","q":"HRN(Highest Response-ratio Next) 스케줄링 방식에 대한 설명으로 옳지 않은 것은?","choices":["대기 시간이 긴 프로세스의 경우 우선 순위가 높아진다.","SJF 기법을 보완하기 위한 방식이다.","긴 작업과 짧은 작업 간의 지나친 불평등을 해소할 수 있다.","우선 순위를 계산하여 그 수치가 가장 낮은 것부터 높은 순으로 우선 순위가 부여된다."],"ans":4,"rate":66,"wiki":[{"title":"HRRN_스케줄링","url":"https://itwiki.kr/w/HRRN_스케줄링"}],"exp":{"concept":"HRN(Highest Response-ratio Next)은 SJF의 단점인 긴 작업의 무한 대기를 줄이려고 대기 시간까지 고려하는 비선점 스케줄링이다. 우선순위 = (대기 시간 + 서비스 시간) ÷ 서비스 시간으로 계산하고, 이 값이 가장 큰 프로세스부터 실행한다.","choices":[{"verdict":"오답","why":"대기 시간이 길수록 분자가 커져 우선순위 값이 높아지므로 옳은 설명이다."},{"verdict":"오답","why":"HRN은 짧은 작업만 우대해 긴 작업이 계속 밀리는 SJF 기법의 단점을 보완하기 위한 방식이다."},{"verdict":"오답","why":"대기 시간을 함께 반영하므로 긴 작업과 짧은 작업 간의 지나친 불평등을 해소할 수 있다."},{"verdict":"정답","why":"HRN은 계산한 우선순위 값이 가장 높은 것부터 실행하므로, 낮은 것부터 우선순위를 준다는 설명은 틀려 정답이다."}],"keywords":[{"term":"HRN 우선순위","desc":"(대기 시간 + 서비스 시간) ÷ 서비스 시간, 큰 값 우선"},{"term":"SJF","desc":"실행 시간이 가장 짧은 작업부터 처리하는 비선점 기법"},{"term":"에이징(Aging)","desc":"오래 기다린 프로세스의 우선순위를 높여 기아 상태 방지"}],"memo":"HRN은 Highest, 이름 그대로 응답 비율이 가장 높은 것부터. 낮은 것부터라는 말이 나오면 오답."}},{"id":"written-2020-1-2-74","no":74,"unit":"프로그래밍 언어 활용","q":"IEEE 802.11 워킹 그룹의 무선 LAN 표준화 현황 중 QoS 강화를 위해 MAC 지원 가능을 채택한 것은?","choices":["802.11a","802.11b","802.11g","802.11e"],"ans":4,"rate":60,"exp":{"concept":"IEEE 802.11은 무선 LAN 표준이고 뒤에 붙은 알파벳으로 세부 표준을 구분한다. 802.11e는 기존 무선 LAN의 MAC 계층에 QoS(서비스 품질) 기능을 강화한 표준이다.","choices":[{"verdict":"오답","why":"802.11a는 5GHz 대역에서 최대 54Mbps 속도를 지원하는 표준이다."},{"verdict":"오답","why":"802.11b는 2.4GHz 대역에서 최대 11Mbps 속도를 지원하는 표준이다."},{"verdict":"오답","why":"802.11g는 2.4GHz 대역에서 최대 54Mbps 속도를 지원하는 표준이다."},{"verdict":"정답","why":"802.11e는 QoS 강화를 위해 MAC 계층 기능을 보완한 표준이므로 정답이다."}],"keywords":[{"term":"802.11e","desc":"QoS 강화를 위한 MAC 기능 보완"},{"term":"802.11i","desc":"무선 LAN 보안(인증, 암호화) 강화"},{"term":"802.11n","desc":"MIMO 기술로 전송 속도 향상"},{"term":"802.11a/b/g","desc":"5GHz 54Mbps / 2.4GHz 11Mbps / 2.4GHz 54Mbps"}],"memo":"e는 QoS, i는 보안. 802.11e와 802.11i는 기능 보완 표준으로 따로 외운다."}},{"id":"written-2020-1-2-75","no":75,"unit":"프로그래밍 언어 활용","q":"C언어에서 사용할 수 없는 변수명은?","choices":["student2019","text-color","_korea","amount"],"ans":2,"rate":66,"wiki":[{"title":"c언어 변수 규칙","url":"https://itwiki.kr/w/c언어 변수 규칙"}],"exp":{"concept":"C 언어 변수명은 영문자, 숫자, 밑줄(_)만 쓸 수 있고, 첫 글자는 숫자가 될 수 없으며, 예약어와 공백은 쓸 수 없다. 하이픈(-)은 빼기 연산자로 해석되므로 변수명에 쓸 수 없다.","choices":[{"verdict":"오답","why":"student2019는 영문자로 시작하고 영문자와 숫자로만 이루어져 사용할 수 있다."},{"verdict":"정답","why":"text-color는 하이픈(-)이 빼기 연산자로 해석되어 text 빼기 color가 되므로 변수명으로 쓸 수 없어 정답이다."},{"verdict":"오답","why":"_korea는 밑줄로 시작할 수 있으므로 사용할 수 있다."},{"verdict":"오답","why":"amount는 영문자로만 이루어져 사용할 수 있다."}],"keywords":[{"term":"변수명 허용 문자","desc":"영문 대소문자, 숫자, 밑줄(_)"},{"term":"첫 글자 규칙","desc":"숫자로 시작할 수 없음, 영문자나 밑줄로 시작"},{"term":"대소문자 구분","desc":"count와 Count는 서로 다른 변수"},{"term":"예약어 금지","desc":"int, if, for 등은 변수명으로 사용 불가"}],"memo":"변수명에 쓸 수 있는 특수문자는 밑줄(_) 하나뿐이다. 하이픈은 빼기."}},{"id":"written-2020-1-2-76","no":76,"unit":"프로그래밍 언어 활용","q":"스크립트 언어가 아닌 것은?","choices":["PHP","Cobol","Basic","Python"],"ans":2,"rate":59,"wiki":[{"title":"스크립트 언어","url":"https://itwiki.kr/w/스크립트 언어"}],"exp":{"concept":"스크립트 언어는 소스 코드를 미리 컴파일하지 않고 인터프리터가 바로 해석해 실행하는 언어다. 출제 기준에서는 PHP, Python, JavaScript, Basic 등을 스크립트 언어로 분류한다. COBOL은 컴파일해서 실행하는 사무 처리용 언어다.","choices":[{"verdict":"오답","why":"PHP는 서버 쪽에서 동작하는 웹 스크립트 언어다."},{"verdict":"정답","why":"COBOL은 사무 처리용으로 개발된 컴파일 방식의 언어로, 스크립트 언어가 아니므로 정답이다."},{"verdict":"오답","why":"Basic은 인터프리터 방식으로 실행되는 언어로, 출제 기준에서 스크립트 언어로 분류된다."},{"verdict":"오답","why":"Python은 인터프리터 방식의 객체지향 스크립트 언어다."}],"keywords":[{"term":"스크립트 언어","desc":"인터프리터로 바로 해석해 실행, PHP, Python, JavaScript, Basic 등"},{"term":"COBOL","desc":"사무 처리용 컴파일 언어"},{"term":"컴파일 언어","desc":"C, C++, COBOL, FORTRAN 등 기계어로 번역 후 실행"}],"memo":"COBOL은 오래된 사무용 컴파일 언어. 스크립트 언어 문제에서 단골 오답이다."}},{"id":"written-2020-1-2-77","no":77,"unit":"프로그래밍 언어 활용","q":"다음의 페이지 참조 열(Page reference string)에 대해 페이지 교체 기법으로 선입선출 알고리즘을 사용할 경우 페이지 부재(Page Fault) 횟수는? (단, 할당된 페이지 프레임 수는 3이고, 처음에는 모든 프레임이 비어 있다.)\n<img src=\"data/img/eip_written_20200606_077.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["13","14","15","20"],"ans":2,"rate":62,"wiki":[{"title":"페이지 교체","url":"https://itwiki.kr/w/페이지 교체"}],"exp":{"concept":"FIFO(First In First Out) 페이지 교체는 프레임이 꽉 찼을 때 가장 먼저 들어온 페이지를 내보낸다. 참조하려는 페이지가 프레임에 없으면 페이지 부재가 한 번 일어난다. 참조 열 7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0(19개)을 프레임 3개로 차례대로 따라가면 부재가 14번 일어난다.","choices":[{"verdict":"오답","why":"13은 실제 부재 횟수 14보다 하나 적다. 마지막 0을 참조할 때도 0이 이미 교체되어 나간 뒤라 부재가 난다는 점을 놓치기 쉽다."},{"verdict":"정답","why":"7, 0, 1(부재 3) → 2(7 교체, 4) → 0 적중 → 3(0 교체, 5) → 0(1 교체, 6) → 4(2 교체, 7) → 2(3 교체, 8) → 3(0 교체, 9) → 0(4 교체, 10) → 3, 2 적중 → 1(2 교체, 11) → 2(3 교체, 12) → 0, 1 적중 → 7(0 교체, 13) → 0(1 교체, 14)이므로 정답이다."},{"verdict":"오답","why":"15는 정답보다 부재를 한 번 더 센 값이다. 19개 참조 중 프레임에 이미 있어 적중하는 것은 5번째 0, 12·13번째 3과 2, 16·17번째 0과 1의 다섯 번뿐이므로 부재는 19 - 5 = 14번이다."},{"verdict":"오답","why":"참조 열 길이가 19이므로 부재가 20번일 수는 없다."}],"keywords":[{"term":"FIFO","desc":"가장 먼저 들어온 페이지를 먼저 교체"},{"term":"LRU","desc":"가장 오랫동안 사용하지 않은 페이지를 교체"},{"term":"OPT","desc":"앞으로 가장 오랫동안 사용하지 않을 페이지를 교체, 부재 최소"},{"term":"페이지 부재(Page Fault)","desc":"참조할 페이지가 주기억장치 프레임에 없는 상황"}],"memo":"처음 프레임을 채우는 부재도 센다. 표를 그려 들어온 순서대로 지우면 실수가 줄어든다."}},{"id":"written-2020-1-2-78","no":78,"unit":"프로그래밍 언어 활용","q":"C언어에서 배열 b[5]의 값은?\n<img src=\"data/img/eip_written_20200606_078.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["0","1","2","3"],"ans":1,"rate":77,"exp":{"concept":"C 언어에서 배열을 선언하며 초기값을 일부만 주면 나머지 원소는 자동으로 0으로 채워진다. static int b[9]={1,2,3};은 b[0]=1, b[1]=2, b[2]=3이고 b[3]부터 b[8]까지는 0이다. 또 static 변수는 초기값을 주지 않아도 0으로 초기화된다.","choices":[{"verdict":"정답","why":"b[5]는 초기값이 주어지지 않은 원소이므로 0으로 채워져 정답이다."},{"verdict":"오답","why":"1은 b[0]의 값이다."},{"verdict":"오답","why":"2는 b[1]의 값이다."},{"verdict":"오답","why":"3은 b[2]의 값이다. 인덱스는 0부터 시작하므로 b[5]는 여섯 번째 원소다."}],"keywords":[{"term":"배열 부분 초기화","desc":"초기값이 모자라면 나머지 원소는 0"},{"term":"배열 인덱스","desc":"0부터 시작, b[9]의 인덱스는 0~8"},{"term":"static 변수","desc":"프로그램 종료 시까지 유지, 초기값 없으면 0으로 초기화"}],"memo":"초기값을 적은 만큼만 채우고 나머지는 0. 인덱스는 0부터 센다."}},{"id":"written-2020-1-2-79","no":79,"unit":"프로그래밍 언어 활용","q":"응집도가 가장 낮은 것은?","choices":["기능적 응집도","시간적 응집도","절차적 응집도","우연적 응집도"],"ans":4,"rate":87,"wiki":[{"title":"응집도","url":"https://itwiki.kr/w/응집도"}],"exp":{"concept":"응집도(Cohesion)는 모듈 안의 구성 요소들이 서로 얼마나 관련 있는지를 나타내며, 높을수록 좋다. 강한 것부터 기능적, 순차적, 교환(통신)적, 절차적, 시간적, 논리적, 우연적 응집도 순이다. 우연적 응집도가 가장 낮다.","choices":[{"verdict":"오답","why":"기능적 응집도는 모듈 내부의 모든 기능이 단일 목적을 위해 수행되는 경우로, 응집도가 가장 높다."},{"verdict":"오답","why":"시간적 응집도는 특정 시간에 처리되는 기능들을 한 모듈에 모은 경우로, 우연적 응집도보다 높다."},{"verdict":"오답","why":"절차적 응집도는 여러 기능 요소들이 순차적으로 수행되는 경우로, 우연적 응집도보다 높다."},{"verdict":"정답","why":"우연적 응집도는 서로 관련 없는 요소들이 우연히 한 모듈에 모인 경우로, 응집도가 가장 낮으므로 정답이다."}],"keywords":[{"term":"응집도 순서(강→약)","desc":"기능적, 순차적, 교환적, 절차적, 시간적, 논리적, 우연적"},{"term":"기능적 응집도","desc":"단일 목적의 기능만 모임, 가장 강함"},{"term":"우연적 응집도","desc":"관련 없는 요소가 모임, 가장 약함"}],"memo":"응집도 강한 순서는 기순교절시논우(기능, 순차, 교환, 절차, 시간, 논리, 우연)."}},{"id":"written-2020-1-2-80","no":80,"unit":"프로그래밍 언어 활용","q":"JAVA 언어에서 접근제한자가 아닌 것은?","choices":["public","protected","package","private"],"ans":3,"rate":78,"exp":{"concept":"Java의 접근 제한자는 클래스나 멤버에 어디서 접근할 수 있는지 정한다. public, protected, default, private 네 가지가 있다. 아무것도 쓰지 않으면 같은 패키지 안에서만 접근 가능한 default가 되며, package는 패키지를 선언하는 예약어이지 접근 제한자가 아니다.","choices":[{"verdict":"오답","why":"public은 모든 클래스에서 접근할 수 있는 접근 제한자다."},{"verdict":"오답","why":"protected는 같은 패키지와 다른 패키지의 하위 클래스에서 접근할 수 있는 접근 제한자다."},{"verdict":"정답","why":"package는 소스 파일이 속한 패키지를 선언하는 예약어로, 접근 제한자가 아니므로 정답이다."},{"verdict":"오답","why":"private은 같은 클래스 안에서만 접근할 수 있는 접근 제한자다."}],"keywords":[{"term":"public","desc":"어디서나 접근 가능"},{"term":"protected","desc":"같은 패키지와 상속받은 하위 클래스에서 접근"},{"term":"default","desc":"제한자를 생략한 경우, 같은 패키지 안에서만 접근"},{"term":"private","desc":"같은 클래스 안에서만 접근"}],"memo":"접근 범위가 넓은 순서는 public, protected, default, private. package라는 제한자는 없다."}},{"id":"written-2020-1-2-81","no":81,"unit":"정보시스템 구축 관리","q":"Rayleigh-Norden 곡선의 노력 분포도를 이용한 프로젝트 비용 산정기법은?","choices":["Putnam 모형","델파이 모형","COCOMO 모형","기능점수 모형"],"ans":1,"rate":56,"exp":{"concept":"Putnam 모형은 소프트웨어 생명주기 전 과정에 걸쳐 사용될 노력의 분포를 가정하는 비용 산정 기법이다. 이 노력 분포를 Rayleigh-Norden 곡선으로 나타낸다. 이를 바탕으로 만든 자동화 도구가 SLIM이다.","choices":[{"verdict":"정답","why":"Putnam 모형은 Rayleigh-Norden 곡선의 노력 분포도를 이용한 비용 산정 기법이므로 정답이다."},{"verdict":"오답","why":"델파이 기법은 여러 전문가의 의견을 조정자가 모아 조정하는 전문가 감정 방식의 비용 산정 기법이다."},{"verdict":"오답","why":"COCOMO 모형은 보헴(Boehm)이 제안한 것으로, 예측한 원시 코드 라인 수(LOC)를 바탕으로 비용을 산정한다."},{"verdict":"오답","why":"기능 점수(FP) 모형은 소프트웨어 기능을 입력, 출력, 질의, 파일 등으로 나눠 점수를 매겨 비용을 산정하는 기법이다."}],"keywords":[{"term":"Putnam 모형","desc":"Rayleigh-Norden 곡선, 자동화 도구 SLIM"},{"term":"COCOMO","desc":"LOC 기반, Boehm 제안, 조직형·반분리형·내장형"},{"term":"기능 점수(FP) 모형","desc":"기능별 가중치로 점수 산출, 자동화 도구 ESTIMACS"},{"term":"델파이 기법","desc":"전문가 여러 명과 조정자 1명"}],"memo":"곡선(Rayleigh-Norden)이 나오면 Putnam, 그 도구는 SLIM."}},{"id":"written-2020-1-2-82","no":82,"unit":"정보시스템 구축 관리","q":"메모리상에서 프로그램의 복귀 주소와 변수사이에 특정 값을 저장해 두었다가 그 값이 변경되었을 경우 오버플로우 상태로 가정하여 프로그램 실행을 중단하는 기술은?","choices":["모드체크","리커버리 통제","시스로그","스택가드"],"ans":4,"rate":75,"wiki":[{"title":"버퍼 오버플로우","url":"https://itwiki.kr/w/버퍼 오버플로우"}],"exp":{"concept":"스택 가드(Stack Guard)는 버퍼 오버플로 공격을 막는 기술이다. 함수의 복귀 주소와 변수 사이에 카나리(Canary)라는 특정 값을 넣어 두고, 이 값이 바뀌면 오버플로가 일어났다고 보고 프로그램을 중단한다. 탄광의 카나리아가 위험을 먼저 알려 주는 것과 같다.","choices":[{"verdict":"오답","why":"모드 체크는 복귀 주소와 변수 사이에 특정 값을 두고 감시하는 오버플로 방지 기술을 가리키는 표준 용어가 아니다."},{"verdict":"오답","why":"리커버리 통제는 장애나 사고가 발생한 뒤 시스템을 원래 상태로 복구하기 위한 통제 활동이다."},{"verdict":"오답","why":"시스로그(Syslog)는 시스템에서 발생하는 이벤트를 기록하는 로그 및 로그 기록 체계다."},{"verdict":"정답","why":"스택 가드는 복귀 주소와 변수 사이에 특정 값을 저장해 두었다가 그 값이 변경되면 오버플로로 판단해 실행을 중단하는 기술이므로 정답이다."}],"keywords":[{"term":"스택 가드(Stack Guard)","desc":"카나리 값 변경 감지로 버퍼 오버플로 방지"},{"term":"스택 실드(Stack Shield)","desc":"복귀 주소를 별도 공간에 저장했다가 비교해 오버플로 방지"},{"term":"ASLR","desc":"메모리 주소 배치를 무작위로 바꿔 공격을 어렵게 함"}],"memo":"스택 가드는 감시 값(카나리)을 두고, 스택 실드는 복귀 주소 사본을 따로 둔다."}},{"id":"written-2020-1-2-83","no":83,"unit":"정보시스템 구축 관리","q":"백도어 탐지 방법으로 틀린 것은?","choices":["무결성 검사","닫힌 포트 확인","로그 분석","SetUID 파일 검사"],"ans":2,"rate":63,"exp":{"concept":"백도어(Backdoor)는 정상 인증 절차를 우회해 시스템에 몰래 들어올 수 있도록 만들어 둔 뒷문이다. 탐지 방법에는 무결성 검사, 열린 포트 확인, 로그 분석, SetUID 파일 검사, 동작 중인 프로세스 확인, 바이러스·백도어 탐지 도구 사용이 있다.","choices":[{"verdict":"오답","why":"무결성 검사는 주요 파일의 해시 값을 비교해 변조 여부를 확인하는 백도어 탐지 방법이다."},{"verdict":"정답","why":"백도어는 외부와 통신하려고 포트를 열어 두므로 확인해야 할 것은 열린 포트다. 닫힌 포트 확인은 탐지 방법이 아니므로 정답이다."},{"verdict":"오답","why":"로그 분석은 접속 기록 등에서 이상 징후를 찾아내는 백도어 탐지 방법이다."},{"verdict":"오답","why":"SetUID 파일 검사는 root 권한으로 실행되도록 설정된 의심 파일을 찾는 백도어 탐지 방법이다."}],"keywords":[{"term":"백도어","desc":"인증 절차를 우회하는 비밀 통로"},{"term":"SetUID","desc":"파일 실행 시 소유자 권한으로 실행되게 하는 설정"},{"term":"백도어 탐지","desc":"무결성 검사, 열린 포트 확인, 로그 분석, SetUID 파일 검사"}],"memo":"백도어는 문을 열어 두는 것이므로 열린 포트를 확인한다. 닫힌 포트는 함정."}},{"id":"written-2020-1-2-84","no":84,"unit":"정보시스템 구축 관리","q":"IP 또는 ICMP의 특성을 악용하여 특정 사이트에 집중적으로 데이터를 보내 네트워크 또는 시스템의 상태를 불능으로 만드는 공격 방법은?","choices":["TearDrop","Smishing","Qshing","Smurfing"],"ans":4,"rate":67,"wiki":[{"title":"스머프 공격","url":"https://itwiki.kr/w/스머프 공격"}],"exp":{"concept":"스머핑(Smurfing)은 출발지 주소를 공격 대상 IP로 위조한 ICMP Echo 요청을 네트워크 전체(브로드캐스트)에 보내, 수많은 응답이 공격 대상에게 몰리도록 하는 서비스 거부 공격이다. IP와 ICMP의 특성을 악용해 특정 사이트에 데이터를 집중시킨다.","choices":[{"verdict":"오답","why":"티어드롭(TearDrop)은 IP 패킷 조각의 순서 번호(Fragment Offset)를 조작해 재조립을 못 하게 만들어 시스템을 다운시키는 공격이다."},{"verdict":"오답","why":"스미싱(Smishing)은 문자 메시지(SMS)에 악성 링크를 넣어 개인정보나 소액 결제를 빼내는 공격이다."},{"verdict":"오답","why":"큐싱(Qshing)은 QR 코드를 이용해 악성 앱 설치나 개인정보 입력을 유도하는 공격이다."},{"verdict":"정답","why":"스머핑은 IP와 ICMP의 특성을 악용해 특정 사이트에 대량의 응답 데이터를 집중시켜 네트워크를 불능 상태로 만드는 공격이므로 정답이다."}],"keywords":[{"term":"스머핑(Smurfing)","desc":"위조한 ICMP Echo를 브로드캐스트해 응답을 대상에 집중"},{"term":"티어드롭(TearDrop)","desc":"Fragment Offset 조작으로 재조립 불가"},{"term":"Ping of Death","desc":"허용 크기를 넘는 ICMP 패킷으로 시스템 마비"},{"term":"SYN Flooding","desc":"TCP 3-way handshake의 SYN만 대량 전송"}],"memo":"ICMP와 브로드캐스트로 데이터를 몰아 보내면 스머핑, 조각 순서 조작이면 티어드롭."}},{"id":"written-2020-1-2-85","no":85,"unit":"정보시스템 구축 관리","q":"CMM(Capability Maturity Model) 모델의 레벨로 옳지 않은 것은?","choices":["최적단계","관리단계","정의단계","계획단계"],"ans":4,"rate":50,"wiki":[{"title":"CMMi","url":"https://itwiki.kr/w/CMMi"}],"exp":{"concept":"CMM(Capability Maturity Model)은 소프트웨어 개발 조직의 업무 능력과 성숙도를 5단계로 평가하는 모델이다. 단계는 초기, 반복, 정의, 관리, 최적화 순이다. 계획 단계라는 레벨은 없다.","choices":[{"verdict":"오답","why":"최적 단계는 프로세스를 지속적으로 개선하는 CMM의 5단계다."},{"verdict":"오답","why":"관리 단계는 정량적인 측정으로 프로세스를 관리하는 CMM의 4단계다."},{"verdict":"오답","why":"정의 단계는 조직 차원의 표준 프로세스가 정의된 CMM의 3단계다."},{"verdict":"정답","why":"계획 단계는 CMM 레벨에 없으므로 정답이다. CMM 레벨은 초기, 반복, 정의, 관리, 최적화다."}],"keywords":[{"term":"1단계 초기(Initial)","desc":"정의된 프로세스 없이 작업자 능력에 의존"},{"term":"2단계 반복(Repeatable)","desc":"이전 경험을 바탕으로 반복 가능한 프로젝트 관리"},{"term":"3단계 정의(Defined)","desc":"조직 표준 프로세스 정의"},{"term":"4단계 관리(Managed)","desc":"정량적 측정으로 프로세스 관리"},{"term":"5단계 최적화(Optimizing)","desc":"지속적인 프로세스 개선"}],"memo":"CMM 단계는 초반정관최(초기, 반복, 정의, 관리, 최적화). 계획은 없다."}},{"id":"written-2020-1-2-86","no":86,"unit":"정보시스템 구축 관리","q":"웹과 컴퓨터 프로그램에서 용량이 적은 데이터를 교환하기 위해 데이터 객체를 속성·값의 쌍 형태로 표현하는 형식으로 자바스크립트(JavaScript)를 토대로 개발되어진 형식은?","choices":["Python","XML","JSON","WEB SEVER"],"ans":3,"rate":86,"wiki":[{"title":"JSON","url":"https://itwiki.kr/w/JSON"}],"exp":{"concept":"JSON(JavaScript Object Notation)은 자바스크립트 문법을 토대로 만든 데이터 교환 형식이다. {\"이름\": \"홍길동\"}처럼 속성과 값의 쌍으로 데이터를 표현하며, 가볍고 사람이 읽기 쉬워 웹에서 데이터를 주고받을 때 널리 쓴다.","choices":[{"verdict":"오답","why":"Python은 데이터 교환 형식이 아니라 범용 프로그래밍 언어다."},{"verdict":"오답","why":"XML은 태그를 사용해 데이터를 구조화하는 마크업 언어로, 자바스크립트를 토대로 개발되지 않았다."},{"verdict":"정답","why":"JSON은 자바스크립트를 토대로 개발되어 속성과 값의 쌍으로 데이터 객체를 표현하는 경량 데이터 교환 형식이므로 정답이다."},{"verdict":"오답","why":"웹 서버(Web Server)는 웹 요청을 받아 응답을 보내 주는 서버 소프트웨어로, 데이터 표현 형식이 아니다."}],"keywords":[{"term":"JSON","desc":"자바스크립트 기반, 속성-값 쌍의 경량 데이터 교환 형식"},{"term":"XML","desc":"태그로 데이터를 구조화하는 확장 가능한 마크업 언어"},{"term":"AJAX","desc":"페이지 전체를 새로 고치지 않고 일부 데이터만 비동기로 주고받는 기법"}],"memo":"JSON의 JS는 JavaScript. 속성-값 쌍이면 JSON."}},{"id":"written-2020-1-2-87","no":87,"unit":"정보시스템 구축 관리","q":"크래커가 침입하여 백도어를 만들어 놓거나, 설정 파일을 변경했을 때 분석하는 도구는?","choices":["trace","tripwire","udpdump","cron"],"ans":2,"rate":68,"wiki":[{"title":"Tripwire","url":"https://itwiki.kr/w/Tripwire"}],"exp":{"concept":"트립와이어(Tripwire)는 시스템의 주요 파일 정보를 미리 데이터베이스로 만들어 두고, 나중에 다시 비교해 변경된 파일을 찾아내는 무결성 점검 도구다. 크래커가 백도어를 심거나 설정 파일을 바꾸면 이를 알아낼 수 있다.","choices":[{"verdict":"오답","why":"trace는 크래커의 백도어나 설정 파일 변경을 분석하는 도구로 출제 범위에서 다루는 표준 도구가 아니다."},{"verdict":"정답","why":"tripwire는 파일의 무결성을 점검해 백도어 생성이나 설정 파일 변경을 분석하는 도구이므로 정답이다."},{"verdict":"오답","why":"udpdump는 출제 범위에서 다루는 표준 보안 도구가 아니다. 네트워크 패킷을 캡처하는 대표 도구는 tcpdump다."},{"verdict":"오답","why":"cron은 UNIX 계열에서 지정한 시간에 작업을 자동 실행하도록 예약하는 스케줄러다."}],"keywords":[{"term":"tripwire","desc":"파일 무결성을 점검해 변조를 탐지"},{"term":"tcpdump","desc":"네트워크 패킷을 캡처해 분석"},{"term":"cron","desc":"UNIX의 작업 예약 스케줄러"}],"memo":"트립와이어는 건드리면 울리는 인계철선. 파일을 건드리면 탐지한다."}},{"id":"written-2020-1-2-88","no":88,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 프레임워크를 적용할 경우 기대효과로 거리가 먼 것은?","choices":["품질보증","시스템 복잡도 증가","개발 용이성","변경 용이성"],"ans":2,"rate":93,"exp":{"concept":"소프트웨어 개발 프레임워크는 개발에 필요한 기본 구조와 공통 기능을 미리 만들어 둔 뼈대다. 이를 적용하면 품질 보증, 개발 용이성, 변경 용이성, 재사용성 향상, 시스템 복잡도 감소 같은 효과를 얻는다.","choices":[{"verdict":"오답","why":"검증된 구조와 공통 기능을 쓰므로 품질이 보증되는 효과가 있다."},{"verdict":"정답","why":"프레임워크는 공통 구조를 제공해 시스템 복잡도를 감소시키므로, 복잡도 증가는 기대 효과가 아니라 정답이다."},{"verdict":"오답","why":"기본 뼈대가 갖춰져 있어 개발이 쉬워지는 효과가 있다."},{"verdict":"오답","why":"구조가 표준화되어 변경이 쉬워지는 효과가 있다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"개발에 필요한 기본 구조와 공통 기능을 제공하는 뼈대"},{"term":"프레임워크 기대 효과","desc":"품질 보증, 개발 용이성, 변경 용이성, 재사용성, 복잡도 감소"},{"term":"제어의 역전(IoC)","desc":"프로그램 흐름을 개발자가 아닌 프레임워크가 제어"}],"memo":"프레임워크를 쓰는 이유는 쉽고 단순해지기 위해서다. 복잡도 증가는 정반대."}},{"id":"written-2020-1-2-89","no":89,"unit":"정보시스템 구축 관리","q":"COCOMO model 중 기관 내부에서 개발된 중소 규모의 소프트웨어로 일괄 자료 처리나 과학기술 계산용, 비즈니스 자료 처리용으로 5만 라인 이하의 소프트웨어를 개발하는 유형은?","choices":["embeded","organic","semi-detached","semi-embeded"],"ans":2,"rate":62,"wiki":[{"title":"COCOMO","url":"https://itwiki.kr/w/COCOMO"}],"exp":{"concept":"COCOMO 모형은 소프트웨어 규모와 유형에 따라 비용을 산정한다. 유형은 조직형(Organic), 반분리형(Semi-detached), 내장형(Embedded) 세 가지다. 조직형은 기관 내부에서 개발하는 5만(50KDSI) 라인 이하의 중소 규모 사무 처리용 소프트웨어다.","choices":[{"verdict":"오답","why":"내장형(Embedded)은 최대형 규모의 트랜잭션 처리 시스템이나 운영체제 등 30만 라인 이상의 소프트웨어 유형이다."},{"verdict":"정답","why":"조직형(Organic)은 기관 내부에서 개발하는 5만 라인 이하의 중소 규모 일괄 자료 처리, 과학 기술 계산, 비즈니스 자료 처리용 소프트웨어 유형이므로 정답이다."},{"verdict":"오답","why":"반분리형(Semi-detached)은 조직형과 내장형의 중간으로, 30만 라인 이하의 트랜잭션 처리 시스템이나 운영체제, DBMS 등의 소프트웨어 유형이다."},{"verdict":"오답","why":"semi-embedded는 COCOMO의 소프트웨어 개발 유형이 아니다."}],"keywords":[{"term":"조직형(Organic)","desc":"5만 라인 이하, 중소 규모 사무용"},{"term":"반분리형(Semi-detached)","desc":"30만 라인 이하, 중간 규모"},{"term":"내장형(Embedded)","desc":"30만 라인 이상, 최대형 규모"},{"term":"COCOMO 모형 종류","desc":"기본형(Basic), 중간형(Intermediate), 발전형(Detailed)"}],"memo":"COCOMO 유형은 조반내(조직형 5만 이하, 반분리형 30만 이하, 내장형 30만 이상)."}},{"id":"written-2020-1-2-90","no":90,"unit":"정보시스템 구축 관리","q":"여러 개의 독립된 통신장치가 UWB(Ultra Wideband)기술 또는 블루투스 기술을 사용하여 통신망을 형성하는 무선 네트워크 기술은?","choices":["PICONET","SCRUM","NFC","WI-SUN"],"ans":1,"rate":52,"exp":{"concept":"피코넷(PICONET)은 여러 개의 독립된 통신 장치가 블루투스나 UWB 기술을 이용해 근거리에서 통신망을 이루는 무선 네트워크 기술이다. 하나의 마스터와 여러 슬레이브 장치로 구성된다.","choices":[{"verdict":"정답","why":"피코넷은 여러 독립된 통신 장치가 UWB 또는 블루투스 기술로 통신망을 형성하는 무선 네트워크 기술이므로 정답이다."},{"verdict":"오답","why":"스크럼(SCRUM)은 팀이 짧은 스프린트 단위로 개발을 반복하는 애자일 개발 방법론이다."},{"verdict":"오답","why":"NFC(Near Field Communication)는 13.56MHz 대역을 쓰는 약 10cm 이내의 근거리 무선 통신 기술이다."},{"verdict":"오답","why":"와이선(Wi-SUN)은 스마트 그리드 같은 유틸리티 서비스를 위해 장거리에서 저전력으로 통신하는 무선 통신 기술이다."}],"keywords":[{"term":"피코넷(PICONET)","desc":"블루투스·UWB로 장치들이 구성하는 근거리 무선망"},{"term":"UWB(Ultra Wideband)","desc":"넓은 주파수 대역을 쓰는 근거리 초고속 무선 통신"},{"term":"NFC","desc":"13.56MHz, 10cm 이내 근거리 무선 통신"},{"term":"스크럼(SCRUM)","desc":"스프린트 단위로 반복하는 애자일 방법론"}],"memo":"피코(Pico)는 아주 작다는 뜻. 작은 범위의 블루투스·UWB 통신망이 피코넷."}},{"id":"written-2020-1-2-91","no":91,"unit":"정보시스템 구축 관리","q":"프로토타입을 지속적으로 발전시켜 최종 소프트웨어 개발까지 이르는 개발방법으로 위험관리가 중심인 소프트웨어 생명주기 모형은?","choices":["나선형 모형","델파이 모형","폭포수 모형","기능점수 모형"],"ans":1,"rate":75,"wiki":[{"title":"나선형_모델","url":"https://itwiki.kr/w/나선형_모델"}],"exp":{"concept":"나선형 모형(Spiral Model)은 보헴(Boehm)이 제안한 생명주기 모형으로, 계획 수립, 위험 분석, 개발 및 검증, 고객 평가를 여러 번 반복하며 점진적으로 완성한다. 매 주기마다 위험 분석을 하므로 위험 관리가 핵심이다.","choices":[{"verdict":"정답","why":"나선형 모형은 프로토타입을 지속적으로 발전시켜 최종 소프트웨어까지 이르며 위험 관리가 중심인 생명주기 모형이므로 정답이다."},{"verdict":"오답","why":"델파이 기법은 전문가들의 의견을 모아 비용을 산정하는 기법이며, 생명주기 모형이 아니다."},{"verdict":"오답","why":"폭포수 모형은 각 단계를 순차적으로 진행하는 모형으로, 위험 분석을 반복하는 구조가 아니다."},{"verdict":"오답","why":"기능 점수 모형은 소프트웨어 기능에 점수를 매겨 비용을 산정하는 기법이며, 생명주기 모형이 아니다."}],"keywords":[{"term":"나선형 모형","desc":"계획, 위험 분석, 개발, 고객 평가를 반복, 위험 관리 중심"},{"term":"폭포수 모형","desc":"단계를 순차적으로 진행, 이전 단계로 돌아가기 어려움"},{"term":"프로토타입 모형","desc":"견본을 만들어 사용자 요구를 확인하며 개발"}],"memo":"나선형은 위험 분석이 핵심. 위험이라는 단어가 나오면 나선형."}},{"id":"written-2020-1-2-92","no":92,"unit":"정보시스템 구축 관리","q":"다음이 설명하는 용어로 옳은 것은?\n<img src=\"data/img/eip_written_20200606_092.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["하둡(Hadoop)","비컨(Beacon)","포스퀘어(Foursquare)","맴리스터(Memristor)"],"ans":1,"rate":80,"wiki":[{"title":"하둡","url":"https://itwiki.kr/w/하둡"}],"exp":{"concept":"하둡(Hadoop)은 오픈 소스 기반의 분산 컴퓨팅 플랫폼이다. 일반 PC급 컴퓨터 여러 대를 묶어 가상의 대형 스토리지를 만들고, 그 안에 빅데이터를 나눠 저장하고 병렬로 처리한다.","choices":[{"verdict":"정답","why":"하둡은 오픈 소스 기반의 분산 컴퓨팅 플랫폼으로, 일반 PC급 컴퓨터로 가상화된 대형 스토리지를 만들고 빅데이터를 효율적으로 저장·처리하므로 정답이다."},{"verdict":"오답","why":"비컨(Beacon)은 블루투스 저전력(BLE) 신호로 근처 스마트 기기의 위치를 인식해 정보를 보내 주는 근거리 통신 장치다."},{"verdict":"오답","why":"포스퀘어(Foursquare)는 사용자 위치를 기반으로 한 소셜 네트워크 서비스다."},{"verdict":"오답","why":"멤리스터(Memristor)는 메모리(Memory)와 저항(Resistor)의 합성어로, 전원이 끊겨도 이전에 흐른 전류 상태를 기억하는 소자다."}],"keywords":[{"term":"하둡(Hadoop)","desc":"오픈 소스 분산 컴퓨팅 플랫폼, 빅데이터 저장·처리"},{"term":"맵리듀스(MapReduce)","desc":"대용량 데이터를 분산 병렬 처리하는 프로그래밍 모델"},{"term":"HDFS","desc":"하둡의 분산 파일 시스템"}],"memo":"빅데이터 + 분산 + 오픈 소스 + 일반 PC 묶음이면 하둡."}},{"id":"written-2020-1-2-93","no":93,"unit":"정보시스템 구축 관리","q":"소인수 분해 문제를 이용한 공개키 암호화 기법에 널리 사용되는 암호 알고리즘 기법은?","choices":["RSA","ECC","PKI","PEM"],"ans":1,"rate":79,"wiki":[{"title":"타원 곡선 암호","url":"https://itwiki.kr/w/타원 곡선 암호"}],"exp":{"concept":"RSA는 아주 큰 두 소수를 곱한 수를 다시 소인수분해하기 어렵다는 점을 이용한 공개키 암호 알고리즘이다. 공개키로 암호화하고 개인키로 복호화한다.","choices":[{"verdict":"정답","why":"RSA는 큰 숫자의 소인수 분해가 어렵다는 점을 이용한 공개키 암호 알고리즘이므로 정답이다."},{"verdict":"오답","why":"ECC(Elliptic Curve Cryptography)는 타원 곡선 위의 이산 대수 문제를 이용한 공개키 암호 알고리즘이다."},{"verdict":"오답","why":"PKI(Public Key Infrastructure)는 공개키 암호를 안전하게 쓰기 위해 인증서를 발급·관리하는 기반 구조이지 암호 알고리즘이 아니다."},{"verdict":"오답","why":"PEM(Privacy Enhanced Mail)은 전자우편의 기밀성, 인증, 무결성을 제공하는 보안 메일 표준이다."}],"keywords":[{"term":"RSA","desc":"소인수 분해의 어려움 이용, 공개키 암호"},{"term":"ECC","desc":"타원 곡선 이산 대수 문제 이용, 공개키 암호"},{"term":"디피-헬만(Diffie-Hellman)","desc":"이산 대수 문제를 이용한 키 교환 알고리즘"},{"term":"PKI","desc":"인증서 기반 공개키 관리 체계"}],"memo":"소인수 분해면 RSA, 타원 곡선이면 ECC."}},{"id":"written-2020-1-2-94","no":94,"unit":"정보시스템 구축 관리","q":"LOC 기법에 의하여 예측된 총 라인수가 50000라인, 프로그래머의 월 평균 생산성이 200라인, 개발에 참여할 프로그래머가 10인 일 때, 개발 소요 기간은?","choices":["25개월","50개월","200개월","2000개월"],"ans":1,"rate":90,"wiki":[{"title":"LOC","url":"https://itwiki.kr/w/LOC"}],"exp":{"concept":"LOC 기법은 예측한 코드 라인 수로 개발 기간과 비용을 추정한다. 개발 기간 = 노력(인월) ÷ 투입 인원이고, 노력(인월) = 총 라인 수 ÷ 1인당 월 평균 생산성이다. 노력 = 50000 ÷ 200 = 250인월이고, 개발 기간 = 250 ÷ 10 = 25개월이다.","choices":[{"verdict":"정답","why":"노력 250인월을 프로그래머 10명으로 나누면 25개월이므로 정답이다."},{"verdict":"오답","why":"50개월은 투입 인원을 5명으로 계산해야 나오는 값으로, 이 문제의 조건과 맞지 않는다."},{"verdict":"오답","why":"200은 1인당 월 평균 생산성(라인 수)이지 개발 기간이 아니다."},{"verdict":"오답","why":"2000개월은 계산식에서 나올 수 없는 값이다. 노력 자체가 250인월이다."}],"keywords":[{"term":"노력(인월)","desc":"총 LOC ÷ 1인당 월 평균 생산성"},{"term":"개발 기간","desc":"노력(인월) ÷ 투입 인원"},{"term":"개발 비용","desc":"노력(인월) × 1인당 월 평균 인건비"}],"memo":"라인 수 ÷ 생산성 = 인월, 인월 ÷ 사람 수 = 개월. 단위를 따라가면 식이 나온다."}},{"id":"written-2020-1-2-95","no":95,"unit":"정보시스템 구축 관리","q":"최대 홉수를 15로 제한한 라우팅 프로토콜은?","choices":["RIP","OSPF","Static","EIGRP"],"ans":1,"rate":71,"wiki":[{"title":"라우팅_프로토콜","url":"https://itwiki.kr/w/라우팅_프로토콜"}],"exp":{"concept":"RIP(Routing Information Protocol)는 거리 벡터 방식의 내부 라우팅 프로토콜로, 목적지까지 거쳐 가는 라우터 수(홉 수)로 최적 경로를 고른다. 최대 홉 수를 15로 제한하며 16 이상은 도달할 수 없는 것으로 본다. 그래서 소규모 네트워크에 알맞다.","choices":[{"verdict":"정답","why":"RIP는 거리 벡터 알고리즘을 쓰며 최대 홉 수를 15로 제한한 라우팅 프로토콜이므로 정답이다."},{"verdict":"오답","why":"OSPF(Open Shortest Path First)는 링크 상태 알고리즘(다익스트라)을 사용하는 라우팅 프로토콜로, 대규모 네트워크에 쓰이며 홉 수 15 제한이 없다."},{"verdict":"오답","why":"Static(정적) 라우팅은 관리자가 경로를 직접 수동으로 설정하는 방식이다."},{"verdict":"오답","why":"EIGRP는 시스코(Cisco)가 개발한 라우팅 프로토콜로, 최대 홉 수 15 제한이 있는 프로토콜이 아니다."}],"keywords":[{"term":"RIP","desc":"거리 벡터, 홉 수 기준, 최대 15홉, 소규모 네트워크"},{"term":"OSPF","desc":"링크 상태, 다익스트라 알고리즘, 대규모 네트워크"},{"term":"BGP","desc":"자율 시스템(AS) 사이의 외부 라우팅 프로토콜"}],"memo":"15홉 제한은 RIP. 16이 되면 무한대(도달 불가)로 본다."}},{"id":"written-2020-1-2-96","no":96,"unit":"정보시스템 구축 관리","q":"컴퓨터 사용자의 키보드 움직임을 탐지해 ID, 패스워드 등 개인의 중요한 정보를 몰래 빼가는 해킹 공격은?","choices":["Key Logger Attack","Worm","Rollback","Zombie Worm"],"ans":1,"rate":91,"wiki":[{"title":"키로거","url":"https://itwiki.kr/w/키로거"}],"exp":{"concept":"키로거 공격(Key Logger Attack)은 사용자가 누르는 키보드 입력을 몰래 기록해 ID, 비밀번호, 계좌 번호 같은 중요한 정보를 빼내는 공격이다.","choices":[{"verdict":"정답","why":"키로거 공격은 키보드 움직임을 탐지해 ID, 패스워드 등 개인 정보를 몰래 빼 가는 해킹 공격이므로 정답이다."},{"verdict":"오답","why":"웜(Worm)은 네트워크를 통해 스스로를 복제하며 퍼져 시스템 부하를 높이는 악성 프로그램이다."},{"verdict":"오답","why":"롤백(Rollback)은 트랜잭션 작업을 취소해 이전 상태로 되돌리는 데이터베이스 명령으로, 공격 기법이 아니다."},{"verdict":"오답","why":"좀비 웜(Zombie Worm)은 출제 범위에서 다루는 표준 공격 용어가 아니다."}],"keywords":[{"term":"키로거(Key Logger)","desc":"키보드 입력을 몰래 기록해 정보 탈취"},{"term":"웜(Worm)","desc":"스스로 복제하며 네트워크로 확산"},{"term":"트로이 목마(Trojan Horse)","desc":"정상 프로그램으로 위장했다가 실행되면 악성 동작"}],"memo":"Key(키보드) + Logger(기록기) = 키보드 입력 기록. 이름 그대로다."}},{"id":"written-2020-1-2-97","no":97,"unit":"정보시스템 구축 관리","q":"테일러링(Tailoring) 개발 방법론의 내부 기준에 해당하지 않는 것은?","choices":["납기/비용","기술환경","구성원 능력","국제표준 품질기준"],"ans":4,"rate":55,"wiki":[{"title":"테일러링","url":"https://itwiki.kr/w/테일러링"}],"exp":{"concept":"테일러링(Tailoring)은 표준 개발 방법론을 프로젝트 상황에 맞게 수정해 쓰는 것이다. 테일러링 기준은 내부 기준과 외부 기준으로 나뉜다. 내부 기준은 목표 환경, 요구사항, 프로젝트 규모(비용·기간), 보유 기술(구성원 능력)이고, 외부 기준은 법적 제약 사항과 국제 표준 품질 기준이다.","choices":[{"verdict":"오답","why":"납기와 비용은 프로젝트 규모(사업비, 개발 기간 등)에 해당하는 내부 기준이다."},{"verdict":"오답","why":"기술 환경은 시스템의 개발 환경과 유형에 해당하는 목표 환경으로, 내부 기준이다."},{"verdict":"오답","why":"구성원 능력은 프로젝트 참여 인력의 보유 기술로, 내부 기준이다."},{"verdict":"정답","why":"국제 표준 품질 기준은 회사 밖에서 정해진 품질 기준을 따르는 것이므로 외부 기준에 해당해 정답이다."}],"keywords":[{"term":"테일러링","desc":"표준 방법론을 프로젝트에 맞게 수정·보완"},{"term":"내부 기준","desc":"목표 환경, 요구사항, 프로젝트 규모, 보유 기술"},{"term":"외부 기준","desc":"법적 제약 사항, 국제 표준 품질 기준"}],"memo":"회사 밖에서 정해진 것(법, 국제 표준)은 외부 기준, 프로젝트 안의 사정은 내부 기준."}},{"id":"written-2020-1-2-98","no":98,"unit":"정보시스템 구축 관리","q":"폭포수 모형의 특징으로 거리가 먼 것은","choices":["개발 중 발생한 요구사항을 쉽게 반영할 수 있다.","순차적인 접근방법을 이용한다.","단계적 정의와 산출물이 명확하다.","모형의 적용 경험과 성공사례가 많다."],"ans":1,"rate":83,"wiki":[{"title":"폭포수_모델","url":"https://itwiki.kr/w/폭포수_모델"}],"exp":{"concept":"폭포수 모형(Waterfall Model)은 분석, 설계, 구현, 테스트, 유지보수를 폭포가 떨어지듯 순서대로 진행하는 가장 오래된 생명주기 모형이다. 단계별 산출물이 명확하고 사례가 많지만, 앞 단계로 되돌아가기 어려워 중간에 생긴 요구사항을 반영하기 힘들다.","choices":[{"verdict":"정답","why":"폭포수 모형은 이전 단계로 돌아가기 어려워 개발 중 발생한 요구사항을 반영하기 어렵다. 쉽게 반영할 수 있다는 설명은 틀려 정답이다."},{"verdict":"오답","why":"폭포수 모형은 각 단계를 차례로 진행하는 순차적 접근 방법을 쓴다."},{"verdict":"오답","why":"폭포수 모형은 단계별 정의가 분명하고 각 단계가 끝날 때마다 산출물이 명확하게 나온다."},{"verdict":"오답","why":"폭포수 모형은 가장 오래된 모형이라 적용 경험과 성공 사례가 많다."}],"keywords":[{"term":"폭포수 모형","desc":"순차적 진행, 단계별 산출물 명확, 변경 반영 어려움"},{"term":"고전적 생명주기","desc":"폭포수 모형의 다른 이름"},{"term":"나선형 모형","desc":"위험 분석을 반복하며 점진적으로 개발"}],"memo":"폭포는 거꾸로 올라갈 수 없다. 그래서 중간 변경 반영이 어렵다."}},{"id":"written-2020-1-2-99","no":99,"unit":"정보시스템 구축 관리","q":"다음 설명의 정보보안 침해 공격 관련 용어는?\n<img src=\"data/img/eip_written_20200606_099.png\" alt=\"문제 이미지\" class=\"q-img\" />","choices":["Smishing","C-brain","Trojan Horse","Ransomware"],"ans":4,"rate":84,"wiki":[{"title":"랜섬웨어","url":"https://itwiki.kr/w/랜섬웨어"},{"title":"스미싱","url":"https://itwiki.kr/w/스미싱"},{"title":"트로이 목마","url":"https://itwiki.kr/w/트로이 목마"}],"exp":{"concept":"랜섬웨어(Ransomware)는 몸값(Ransom)과 소프트웨어(Software)를 합친 말이다. 사용자 컴퓨터에 침입해 문서나 파일을 암호화해 열지 못하게 한 뒤, 암호를 풀어 주는 대가로 돈을 요구하는 악성 프로그램이다.","choices":[{"verdict":"오답","why":"스미싱(Smishing)은 문자 메시지(SMS)와 피싱(Phishing)을 합친 말로, 문자 메시지의 링크로 개인정보를 빼내는 공격이다."},{"verdict":"오답","why":"C-brain은 최초의 PC 바이러스로 알려진 브레인(Brain) 바이러스를 가리키며, 파일을 암호화해 돈을 요구하는 공격이 아니다."},{"verdict":"오답","why":"트로이 목마(Trojan Horse)는 정상 프로그램으로 위장해 있다가 실행되면 악성 동작을 하는 프로그램으로, 자기 복제는 하지 않는다."},{"verdict":"정답","why":"랜섬웨어는 내부 문서 파일 등을 암호화해 열지 못하게 하고 암호 해독 프로그램을 대가로 돈을 요구하는 공격이므로 정답이다."}],"keywords":[{"term":"랜섬웨어(Ransomware)","desc":"파일을 암호화하고 복호화 대가로 금전 요구"},{"term":"스미싱(Smishing)","desc":"SMS와 피싱의 합성, 문자 링크로 정보 탈취"},{"term":"트로이 목마","desc":"정상 프로그램으로 위장한 악성 프로그램, 자기 복제 안 함"}],"memo":"Ransom은 인질의 몸값. 파일을 인질로 잡고 돈을 요구하면 랜섬웨어."}},{"id":"written-2020-1-2-100","no":100,"unit":"정보시스템 구축 관리","q":"시스템 내의 정보는 오직 인가된 사용자만 수정할 수 있는 보안 요소는?","choices":["기밀성","부인방지","가용성","무결성"],"ans":4,"rate":46,"wiki":[{"title":"보안","url":"https://itwiki.kr/w/보안"}],"exp":{"concept":"정보보안의 3대 요소는 기밀성, 무결성, 가용성이다. 기밀성은 인가된 사용자만 정보에 접근(열람)할 수 있는 것, 무결성은 인가된 사용자만 정보를 수정할 수 있는 것, 가용성은 인가된 사용자가 필요할 때 언제든 쓸 수 있는 것이다.","choices":[{"verdict":"오답","why":"기밀성(Confidentiality)은 인가된 사용자만 정보에 접근할 수 있도록 하는 보안 요소로, 수정 권한이 아니라 열람 통제에 초점이 있다."},{"verdict":"오답","why":"부인 방지(Non-repudiation)는 데이터를 주고받은 사실을 나중에 부인하지 못하도록 증거를 남기는 보안 요소다."},{"verdict":"오답","why":"가용성(Availability)은 인가된 사용자가 필요할 때 언제든지 정보를 사용할 수 있도록 하는 보안 요소다."},{"verdict":"정답","why":"무결성(Integrity)은 시스템 내의 정보를 오직 인가된 사용자만 수정할 수 있도록 하는 보안 요소이므로 정답이다."}],"keywords":[{"term":"기밀성","desc":"인가된 사용자만 접근(열람) 가능"},{"term":"무결성","desc":"인가된 사용자만 수정 가능"},{"term":"가용성","desc":"인가된 사용자가 필요할 때 사용 가능"},{"term":"인증(Authentication)","desc":"사용자가 정당한지 확인"}],"memo":"보기만 막으면 기밀성, 고치는 것을 막으면 무결성, 쓸 수 있게 보장하면 가용성."}}]};